  var SETTLE_MS = 160;
  var WARM_MS = 400;

  var settleTimer = 0;
  var warmTimer = 0;

  function settled(zoomed) {
    if (zooming()) {
      window.clearTimeout(settleTimer);
      settleTimer = window.setTimeout(function () { settled(true); }, SETTLE_MS);
      return;
    }
    window.clearTimeout(settleTimer);
    if (zoomed) syncMarkers();
    paintLabels();
    warmTiles();
    if (state.find && dom.findOut && !dom.findOut.hidden) renderFound();
  }

  function warmTiles() {
    window.clearTimeout(warmTimer);
    warmTimer = window.setTimeout(function () {
      if (map) TTBBasemap.warm(map, { dark: isDarkStyle(state.style) });
    }, WARM_MS);
  }

  function pinIcon() {
    return L.divIcon({
      className: 'pin-mark',
      html: '<span class="pin-face"></span>',
      iconSize: [PIN_BOX, PIN_BOX],
      iconAnchor: [PIN_BOX / 2, PIN_BOX / 2],
      tooltipAnchor: [0, 0]
    });
  }

  function buildMarkers() {
    var muted = cssVar('--muted') || '#536879';

    allPlaces().forEach(function (place) { addPin(place, muted); });

    fitToPins();
    paintMarkers();   /* also syncs; gives every pin its filmed or unfilmed face */
  }

  function addPins(places) {
    var muted = cssVar('--muted') || '#536879';
    places.forEach(function (place) {
      if (!markers[place.id]) addPin(place, muted);
    });
  }

  function dropPins(places) {
    places.forEach(function (place) {
      var marker = markers[place.id];
      if (marker) {
        if (map && map.hasLayer(marker)) map.removeLayer(marker);
        delete markers[place.id];
      }
      var ring = closedRings[place.id];
      if (ring) {
        if (map && map.hasLayer(ring)) map.removeLayer(ring);
        delete closedRings[place.id];
      }
    });
  }

  function addPin(place, muted) {
    var marker = L.marker([place.lat, place.lng], {
      icon: pinIcon(),
      keyboard: false,        /* the button semantics are added by hand below */
      bubblingMouseEvents: false
    });

    marker.bindTooltip(place.name, {
      className: 'pin-tip',
      direction: 'top',
      offset: [0, -15],
      opacity: 1
    });

    marker.on('click', function () { selectPlace(place.id, { fly: false }); });

    marker.on('add', function () {
      var node = marker.getElement();
      if (!node) return;
      node.setAttribute('tabindex', '0');
      node.setAttribute('role', 'button');
      node.setAttribute('aria-label', t('openPlace', { name: place.name }) +
        (place.closed ? ', ' + shutWord(place) : ''));
      node.addEventListener('keydown', function (ev) {
        if (ev.key === 'Enter' || ev.key === ' ' || ev.key === 'Spacebar') {
          ev.preventDefault();
          selectPlace(place.id, { fly: false });
        }
      });
      dressPin(place);
    });

    markers[place.id] = marker;
    marker.addTo(map);

    if (place.closed) {
      var ring = L.circleMarker([place.lat, place.lng], {
        radius: PIN_D / 2 + 4,
        weight: 1.5,
        color: muted,
        opacity: .9,
        dashArray: '2 3',
        fill: false,
        className: 'pin-shut',
        interactive: false
      });
      closedRings[place.id] = ring;
      ring.addTo(map);
      if (ring.bringToBack) ring.bringToBack();
    }
  }

  var FIT_FLOOR = 12;

  var PAN_MS = 1.1;
  var FLY_MS = 1.2;

  function travelTo(centre, zoom, animate) {
    if (!animate || reduceMotion()) { map.setView(centre, zoom, { animate: false }); return; }
    if (map.getBounds().contains(centre) && Math.abs(zoom - map.getZoom()) <= 2) {
      map.setView(centre, zoom, { animate: true, duration: PAN_MS });
      return;
    }
    map.flyTo(centre, zoom, { duration: FLY_MS });
  }

  function fitLatLngs(pts, opts) {
    if (!map || !pts.length) return;
    var o = opts || {};
    var bounds = L.latLngBounds(pts);
    var pad = isNarrow() ? L.point(48, 48) : L.point(96, 96);

    var cover = null;
    if (o.clearPanel && dom.panel.classList.contains('is-open')) {
      cover = stripCover();
    } else if (isNarrow() && !document.body.classList.contains('panel-open')) {
      cover = chromeCover();
    }
    if (cover) pad = L.point(pad.x + cover.l + cover.r, pad.y + cover.t + cover.b);

    var floor = o.floor == null ? FIT_FLOOR : o.floor;
    var zoom = Math.max(
      Math.min(Math.floor(map.getBoundsZoom(bounds, false, pad)), o.maxZoom == null ? 16 : o.maxZoom),
      floor
    );

    var centre = bounds.getCenter();
    if (cover) {
      var off = map.project(centre, zoom);
      off.x -= (cover.l - cover.r) / 2;
      off.y -= (cover.t - cover.b) / 2;
      centre = map.unproject(off, zoom);
    }

    travelTo(centre, zoom, !!o.animate);
  }

  function chromeCover() {
    var box = map.getContainer().getBoundingClientRect();
    var c = { l: 0, t: 0, r: 0, b: 0 };
    var bar = document.getElementById('filter-bar');
    var r = bar && bar.getBoundingClientRect();
    if (r && r.height) c.t = Math.max(0, r.bottom - box.top);
    r = dom.rail && dom.rail.getBoundingClientRect();
    var disc = dom.btnFlash || dom.btnRandom;
    if (r && r.height > r.width && disc) c.l = Math.max(0, r.left - box.left + disc.offsetHeight);
    r = dom.btnLocate && !dom.btnLocate.hidden && dom.btnLocate.getBoundingClientRect();
    if (r && r.height) c.b = Math.max(0, box.bottom - r.top);
    if (c.l > box.width - 160 || c.t + c.b > box.height - 160) return null;
    return c;
  }

  function stripCover() {
    var box = map.getContainer().getBoundingClientRect();
    var narrow = isNarrow();
    var behind = narrow ? dom.panel.offsetHeight : dom.panel.offsetWidth;
    if (behind > (narrow ? box.height : box.width) - 120) return null;

    var panel = narrow ? { l: 0, t: 0, r: 0, b: behind } : { l: 0, t: 0, r: behind, b: 0 };
    var c = { l: 0, t: 0, r: panel.r, b: panel.b };
    var bar = dom.filterBar && dom.filterBar.getBoundingClientRect();
    if (bar && bar.height) c.t = Math.max(0, bar.bottom - box.top);
    var rail = dom.rail && dom.rail.getBoundingClientRect();
    if (rail && rail.height) {
      if (narrow && rail.height < rail.width) c.b = Math.max(c.b, box.bottom - rail.top);
      if (!narrow && rail.height > rail.width) c.l = Math.max(0, rail.right - box.left);
    }
    var arrow = narrow && dom.btnLocate && !dom.btnLocate.hidden && dom.btnLocate.getBoundingClientRect();
    if (arrow && arrow.height && arrow.top > c.t) c.b = Math.max(c.b, box.bottom - arrow.top);
    if (c.l + c.r > box.width - 160 || c.t + c.b > box.height - 160) return panel;
    return c;
  }

  function fitToPins(opts) {
    var pool = visiblePlaces();
    if (!pool.length) pool = state.places;
    fitLatLngs(pool.map(function (p) { return [p.lat, p.lng]; }), opts);
  }

  function anyInView(places) {
    if (!map || !places.length) return false;
    var size = map.getSize();
    var right = size.x;
    var bottom = size.y;

    if (dom.panel.classList.contains('is-open')) {
      if (isNarrow()) bottom = size.y - dom.panel.offsetHeight;
      else right = size.x - dom.panel.offsetWidth;
    }
    if (bottom < 80 || right < 80) return true;

    return places.some(function (p) {
      var pt = map.latLngToContainerPoint([p.lat, p.lng]);
      return pt.x >= 0 && pt.x <= right && pt.y >= 0 && pt.y <= bottom;
    });
  }

  function markerColours() {
    return {
      lit: cssVar('--accent-lit') || '#0072ce',
      muted: cssVar('--muted') || '#536879',
      paper: cssVar('--paper') || '#f2f8ff',
      here: cssVar('--here') || '#c1420b'
    };
  }

  function isChosen(place) { return !!place && place.id === state.selected; }
  function isKept(place) {
    return !!place && !!state.marked && place.id === state.marked && place.id !== state.selected;
  }
  function isLit(place) { return isChosen(place) || isKept(place); }

  function pinSize(place) {
    if (isChosen(place)) return PIN_D_SELECTED;
    if (isKept(place)) return PIN_D_KEPT;
    if (place.standIn) return PIN_D;
    return pinDepth(place) === 'words' ? PIN_D_WORDS : PIN_D;
  }

  function pinOf(place) {
    if (!place.standIn) return 'mark';
    if (state.list && isOnList(place.id)) return TTBPins.ofList(state.list);
    return TTBPins.forKinds(place.kitchens, place.types);
  }

  function pinDepth(place) {
    if (place.reel) return 'reel';
    if (place.photos && place.photos.length) return 'photos';
    return 'words';
  }

  var DEPTH_GLYPH = {
    reel: '<svg viewBox="0 0 10 10" focusable="false"><circle cx="5" cy="5" r="3.9"/></svg>',
    photos: '<svg viewBox="0 0 10 10" focusable="false"><path fill-rule="evenodd" d="M5 1.1a3.9 3.9 0 100 7.8 3.9 3.9 0 000-7.8zm0 1.7a2.2 2.2 0 110 4.4 2.2 2.2 0 010-4.4z"/></svg>',
    words: '<svg viewBox="0 0 10 10" focusable="false"><circle cx="5" cy="5" r="2.2"/></svg>'
  };

  function depthMarkKey(place) {
    var depth = pinDepth(place);
    return depth === 'reel'
      ? (reelProvider(place.reel) === 'tiktok' ? 'markVideo' : 'markReel')
      : depth === 'photos' ? 'markPhotos' : 'markNone';
  }

  var SHUT_GLYPH = '<svg viewBox="0 0 10 10" focusable="false"><circle cx="5" cy="5" r="3.9" stroke-dasharray="1.7 1.7"/></svg>';

  var PLAY_GLYPH = '<svg viewBox="0 0 10 10" focusable="false"><path d="M3 1.8v6.4L8.4 5z"/></svg>';

  function isPaused(place) {
    return place.closed === 'temporary';
  }

  function shutWord(place) {
    return t(isPaused(place) ? 'venuesShutFor' : 'closed');
  }

  function shutMark(place) {
    return el('span', { className: 'shut-mark' }, [
      el('span', { className: 'shut-glyph', 'aria-hidden': 'true', html: SHUT_GLYPH }),
      el('span', { textContent: shutWord(place) })
    ]);
  }

  function closedNoteKey(place) {
    if (isPaused(place)) return 'closedTempNote';
    var depth = pinDepth(place);
    if (depth === 'reel') {
      return reelProvider(place.reel) === 'tiktok' ? 'closedVideoNote' : 'closedReelNote';
    }
    return depth === 'photos' ? 'closedPhotosNote' : 'closedNote';
  }

  function depthMark(place) {
    var depth = pinDepth(place);
    var key = depthMarkKey(place);
    return el('span', { className: 'depth-mark is-' + depth }, [
      el('span', { className: 'depth-glyph', 'aria-hidden': 'true', html: DEPTH_GLYPH[depth] }),
      el('span', { textContent: t(key) })
    ]);
  }

  function tooltipFor(marker, name, permanent, chosen, kept) {
    marker.unbindTooltip();
    marker.bindTooltip(name, {
      className: 'pin-tip' + (chosen ? ' pin-tip-on' : '') +
        (kept ? ' pin-tip-kept' : '') +
        (permanent && !chosen && !kept ? ' pin-tip-quiet' : ''),
      direction: 'top',
      offset: [0, chosen ? -23 : (kept ? -20 : (permanent ? -18 : -15))],
      opacity: 1,
      interactive: !!permanent,
      permanent: !!permanent
    });
  }

  var LABEL_ZOOM = 14;
  var LABEL_H = 24;
  var soloPins = {};

  function labelBox(place) {
    var pt = map.latLngToContainerPoint([place.lat, place.lng]);
    var w = 20 + place.name.length * 7.3;   /* padding plus the display face */
    return { x: pt.x - w / 2, y: pt.y - 19 - LABEL_H, w: w, h: LABEL_H, px: pt.x, py: pt.y };
  }

  function hits(a, b) {
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
  }

  function labelPlan() {
    var plan = {};
    if (!map || map.getZoom() < LABEL_ZOOM) return plan;

    var size = map.getSize();
    var queue = visiblePlaces().filter(function (p) { return soloPins[p.id]; });

    var taken = [];
    queue.forEach(function (p) {
      var pt = map.latLngToContainerPoint([p.lat, p.lng]);
      var r = Math.max(pinSize(p), PIN_D) / 2 + 2;
      taken.push({ x: pt.x - r, y: pt.y - r, w: r * 2, h: r * 2 });
    });
    clusterPins.forEach(function (pin) {
      var pt = map.latLngToContainerPoint(pin.getLatLng());
      var r = (pin.options.icon.options.iconSize[0] / 2) + 3;
      taken.push({ x: pt.x - r, y: pt.y - r, w: r * 2, h: r * 2 });
    });

    queue.sort(function (a, b) {
      if (isLit(a) === isLit(b)) return 0;
      return isLit(a) ? -1 : 1;
    });

    queue.forEach(function (place) {
      var box = labelBox(place);
      if (box.x < 4 || box.x + box.w > size.x - 4 || box.y < 4 || box.y + box.h > size.y) return;
      for (var i = 0; i < taken.length; i++) if (hits(box, taken[i])) return;
      taken.push(box);
      plan[place.id] = true;
    });
    return plan;
  }

  function paintLabels() {
    if (!map) return;
    var plan = labelPlan();
    allPlaces().forEach(function (place) {
      var marker = markers[place.id];
      if (!marker) return;
      var chosen = isChosen(place);
      var kept = isKept(place);
      var wants = chosen || kept || !!plan[place.id];
      var tip = marker.getTooltip();
      var cls = (tip && tip.options.className) || '';
      var isOn = !!(tip && tip.options.permanent);
      var wasChosen = cls.indexOf('pin-tip-on') !== -1;
      var wasKept = cls.indexOf('pin-tip-kept') !== -1;
      if (!tip || isOn !== wants || wasChosen !== chosen || wasKept !== kept) {
        tooltipFor(marker, place.name, wants, chosen, kept);
      }
    });
  }

  function clearHalo() {
    if (haloMarker && map) map.removeLayer(haloMarker);
    haloMarker = null;
  }

  function dressPin(place, colours) {
    var marker = markers[place.id];
    if (!marker) return;
    var node = marker.getElement();
    if (!node) return;              /* swallowed by a cluster, nothing to dress */

    var c = colours || markerColours();
    var chosen = isChosen(place);
    var kept = isKept(place);
    var depth = pinDepth(place);
    var d = pinSize(place);

    node.classList.add('pin-mark');
    ['reel', 'photos', 'words'].forEach(function (kind) {
      node.classList.toggle('is-' + kind, depth === kind);
    });
    node.classList.toggle('is-chosen', chosen);
    node.classList.toggle('is-kept', kept);
    node.classList.toggle('is-shut', !!place.closed);
    node.classList.toggle('is-paused', isPaused(place));
    node.style.setProperty('--pin-d', d + 'px');

    var wears = pinOf(place);
    TTBPins.dress(node, wears);
    var face = node.querySelector('.pin-face');
    if (face) face.textContent = wears === 'mark' ? '' : TTBPins.glyph(wears);

    if (place.closed === true) node.style.setProperty('--pin-tone', c.muted);
    else if (place.closed) node.style.removeProperty('--pin-tone');
    else if (chosen || kept) node.style.setProperty('--pin-tone', c.lit);
    else node.style.removeProperty('--pin-tone');

    if (marker.setZIndexOffset) marker.setZIndexOffset(chosen ? 400 : (kept ? 300 : 0));
  }

  function paintMarkers() {
    var c = markerColours();
    syncMarkers();

    allPlaces().forEach(function (place) {
      var marker = markers[place.id];
      if (!marker) return;

      dressPin(place, c);

      var ring = closedRings[place.id];
      if (ring) {
        ring.setStyle({ color: c.muted });
        ring.setRadius(Math.max(pinSize(place), PIN_D) / 2 + 4);
      }
    });

    paintLabels();

    clearHalo();
    var place = byId(state.selected || state.marked);
    if (place && map) {
      var lit = isChosen(place);
      haloMarker = L.circleMarker([place.lat, place.lng], {
        radius: pinSize(place) / 2 + 7,
        weight: 2,
        color: c.lit,
        opacity: lit ? .85 : .6,
        fill: false,
        className: 'pin-halo' + (lit ? '' : ' pin-halo-kept'),
        interactive: false
      }).addTo(map);
      if (haloMarker.bringToBack) haloMarker.bringToBack();
    }

    if (hereMarker) {
      hereMarker.setStyle({ color: c.paper, fillColor: c.here });
    }
    if (hereAccuracy) {
      hereAccuracy.setStyle({ color: c.here, fillColor: c.here });
    }
    if (routeLine) {
      routeLine.eachLayer(function (stretch) {
        if (stretch.options.tone) stretch.setStyle({ color: c[stretch.options.tone] });
      });
    }
  }

  var lastSheetKey = null;

  function focusOn(place, zoomIn) {
    if (!map) return;
    var size = map.getSize();
    var zoom = zoomIn ? Math.max(map.getZoom(), FOCUS_ZOOM) : map.getZoom();

    var wantX = size.x / 2;
    var wantY = size.y / 2;

    if (dom.panel.classList.contains('is-open')) {
      if (isNarrow()) {
        var strip = size.y - dom.panel.offsetHeight;
        wantY = Math.min(Math.max(strip / 2 + 26, 104), Math.max(strip - 24, 104));
      } else {
        wantX = Math.max((size.x - dom.panel.offsetWidth - 32) / 2, 80);
      }
    }

    var pt = map.project([place.lat, place.lng], zoom);
    var centre = map.unproject(pt.add(L.point(size.x / 2 - wantX, size.y / 2 - wantY)), zoom);
    travelTo(centre, zoom, true);
  }

  function sheetKey() {
    var cls = document.body.classList;
    return state.view + '|' +
      (cls.contains('sheet-peek') ? 'peek' : cls.contains('sheet-full') ? 'full' : 'low');
  }

  var refocusTimer = null;

  function cancelRefocus() {
    if (refocusTimer) { window.clearTimeout(refocusTimer); refocusTimer = null; }
  }

  function refocus(place, zoomIn, withHere) {
    var key = sheetKey();
    var resizing = isNarrow() && key !== lastSheetKey;
    lastSheetKey = key;
    cancelRefocus();
    var go = function () {
      if (!withHere || !frameWithHere(place)) focusOn(place, zoomIn);
    };
    if (!resizing || reduceMotion()) { go(); return; }
    refocusTimer = window.setTimeout(function () { refocusTimer = null; go(); }, 300);
  }

  function frameWithHere(place) {
    if (hereAway(place) == null) return false;
    var here = hereMarker.getLatLng();
    fitLatLngs([[here.lat, here.lng], [place.lat, place.lng]], {
      animate: true,
      maxZoom: HERE_ZOOM,
      floor: 0,
      clearPanel: true
    });
    return true;
  }

  function hereAway(place) {
    if (!hereMarker || !place) return null;
    var away = hereMarker.getLatLng().distanceTo(L.latLng(place.lat, place.lng));
    return away > HERE_MAX_M ? null : away;
  }

  function farBadge(place) {
    var away = hereAway(place);
    if (away == null) return null;
    return el('span', { className: 'list-far', textContent: farWords(away / 1000) });
  }

  var SAVED_KEY = 'ttb.saved';

  var SAVED_FILTER = 'saved';

  function loadSaves() {
    return fetch('/api/saves', { headers: { accept: 'application/json' } })
      .then(function (res) { return res.ok ? res.json() : {}; })
      .then(function (counts) {
        state.saves = counts && typeof counts === 'object' ? counts : {};
        paintSave();
        if (state.view === 'list' && dom.panel.classList.contains('is-open')) renderList();
      })
      .catch(function () { /* no counts is a fine state to be in */ });
  }

  function readSaved() {
    var raw = storeGet(SAVED_KEY);
    var ids = [];
    if (raw) {
      try {
        var parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) ids = parsed;
      } catch (e) { /* unreadable is the same as none */ }
    }
    state.saved = keptSaves(ids);
  }

  function keptSaves(ids) {
    var seen = {};
    return ids.filter(function (id) {
      if (typeof id !== 'string' || !id || seen[id]) return false;
      if (/^[a-z0-9-]+$/.test(id) && !byId(id)) return false;
      seen[id] = true;
      return true;
    });
  }

  var savedSeating = false;

  function seatSaved(then) {
    if (state.active.indexOf(SAVED_FILTER) === -1) { if (then) then(); return; }
    var missing = state.saved.filter(function (id) { return !byId(id); });
    if (!missing.length || savedSeating) { if (then) then(); return; }

    savedSeating = true;
    findLoad().then(function (roll) {
      savedSeating = false;
      var rows = {};
      roll.forEach(function (row) { rows[row.id] = row; });
      var seated = [];
      missing.forEach(function (id) {
        if (rows[id] && !byId(id)) seated.push(foundStandIn(rows[id]));
      });
      if (seated.length) {
        state.savedPlaces = state.savedPlaces.concat(seated);
        addPins(seated);
        if (state.view === 'list' && dom.panel.classList.contains('is-open')) renderPanel();
        paintMarkers();
        if (!then) fitToPins({ animate: true });
      }
      if (then) then();
    });
  }

  function isSaved(id) { return state.saved.indexOf(id) !== -1; }

  function markSaved(id, on) {
    var at = state.saved.indexOf(id);
    if (on && at === -1) state.saved.unshift(id);
    if (!on && at !== -1) state.saved.splice(at, 1);
    storeSet(SAVED_KEY, JSON.stringify(state.saved));
  }

  function savedCount() { return state.saved.length; }

  function saveCount(id) {
    var n = state.saves[id];
    return typeof n === 'number' && n > 0 ? n : 0;
  }

  var SAVE_GLYPH = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">' +
    '<path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/></svg>';

  function saveMark(place) {
    var n = saveCount(place.id);
    if (!n) return null;
    return el('span', { className: 'save-mark' }, [
      el('span', { className: 'save-mark-ico', 'aria-hidden': 'true', html: SAVE_GLYPH }),
      el('span', { textContent: String(n) })
    ]);
  }

  function paintSave() {
    var place = state.view === 'detail' && state.selected ? byId(state.selected) : null;
    dom.panelSave.hidden = !place;
    if (!place) return;

    var n = saveCount(place.id);
    var mine = isSaved(place.id);
    dom.panelSave.setAttribute('aria-pressed', String(mine));
    dom.panelSaveN.textContent = n ? String(n) : '';
    dom.panelSave.classList.toggle('has-n', !!n);

    var label = t('savePlace');
    if (n) label += ', ' + (n === 1 ? t('saveCountOne') : t('saveCount', { n: n }));
    dom.panelSave.setAttribute('aria-label', label);
    dom.panelSave.setAttribute('title', label);
  }

  function paintDirections() {
    var place = state.view === 'detail' && state.selected ? byId(state.selected) : null;
    dom.panelDirections.hidden = !place || typeof place.lat !== 'number' || typeof place.lng !== 'number';
    if (dom.panelDirections.hidden) return;
    var row = googleFor[place.id];
    var key = place.google ? place.id : row && row !== ASKING ? row.id : '';
    dom.panelDirections.href = directionsUrl(place, key);
    dom.panelDirections.setAttribute('aria-label', t('directions'));
    dom.panelDirections.setAttribute('title', t('directions'));
  }

  var ROUTE_TRAVEL = { foot: 'walking', bus: 'transit', car: 'driving' };
  var ROUTE_NONE = { foot: 'routeNone', bus: 'routeNoBus', car: 'routeNoCar' };

  function showRoute(place) {
    var token = ++routeToken;
    var mode = routeMode;
    routeFor = place.id;
    clearRouteLine();
    paintRouteModes();
    dom.routeOut.href = mode === 'car'
      ? 'https://waze.com/ul?ll=' + place.lat + ',' + place.lng + '&navigate=yes'
      : dom.panelDirections.href + '&travelmode=' + ROUTE_TRAVEL[mode];
    dom.routeOut.textContent = t(mode === 'car' ? 'routeWaze' : 'routeGoogle');
    dom.routeSay.textContent = t('routeFinding');
    dom.routeBar.hidden = false;
    document.body.classList.add('route-on');

    var here = hereMarker ? hereMarker.getLatLng() : null;
    var got = here ? Promise.resolve({ lat: here.lat, lng: here.lng }) : (hereQuiet = true, locateOnce());
    got.then(function (from) {
      if (token !== routeToken) return null;
      if (!from) { dom.routeSay.textContent = t('routeLocate'); return null; }
      return fetch('/api/route?mode=' + mode + '&from=' + from.lat + ',' + from.lng + '&to=' + place.lat + ',' + place.lng)
        .then(function (res) { return res.ok ? res.json() : null; })
        .then(function (way) {
          if (token !== routeToken) return;
          if (mode === 'bus') {
            if (!way || !way.trips || !way.trips.length) { dom.routeSay.textContent = t('routeNoBus'); return; }
            routeTrips = way.trips;
            drawTrip(0);
            return;
          }
          if (!way || !way.line || way.line.length < 2) { dom.routeSay.textContent = t(ROUTE_NONE[mode]); return; }
          drawRoute(way, mode);
        });
    }).catch(function () {
      if (token === routeToken) dom.routeSay.textContent = t(ROUTE_NONE[mode]);
    });
  }

  function paintRouteModes() {
    var tabs = dom.routeModes.querySelectorAll('.route-mode');
    for (var i = 0; i < tabs.length; i++) {
      tabs[i].setAttribute('aria-pressed', String(tabs[i].getAttribute('data-mode') === routeMode));
    }
  }

  function routeStretch(line, colour, tone, dashed) {
    return L.polyline(line, {
      color: colour,
      tone: tone,
      weight: dashed ? 4 : 5,
      opacity: .85,
      dashArray: dashed ? '2 8' : null,
      lineCap: 'round',
      lineJoin: 'round',
      className: 'route-line',
      interactive: false
    }).addTo(routeLine);
  }

  function fitRoute() {
    map.fitBounds(routeLine.getBounds(), {
      paddingTopLeft: [40, isNarrow() ? 220 : 90],
      paddingBottomRight: [40, dom.routeBar.offsetHeight + 40],
      maxZoom: 17
    });
  }

  function routeDistance(m) {
    return m < 1000 ? t('askMetres', { n: Math.max(10, Math.round(m / 10) * 10) })
      : t('askKm', { n: formatDecimal(m / 1000, 1) });
  }

  function drawRoute(way, mode) {
    routeLine = L.featureGroup().addTo(map);
    routeStretch(way.line, markerColours().here, 'here', false);
    dom.routeSay.textContent = t(mode === 'car' ? 'routeCar' : 'routeWalk', {
      min: Math.max(1, Math.round(way.seconds / 60)),
      dist: routeDistance(way.meters)
    });
    fitRoute();
  }

  function drawTrip(n) {
    var trip = routeTrips[n];
    var c = markerColours();
    clearRouteLine();
    routeLine = L.featureGroup().addTo(map);
    trip.legs.forEach(function (leg) {
      if (leg.line.length < 2) return;
      if (leg.name === undefined) routeStretch(leg.line, c.here, 'here', true);
      else if (leg.color) routeStretch(leg.line, '#' + leg.color, null, false);
      else routeStretch(leg.line, c.lit, 'lit', false);
    });
    var rides = tripRides(trip);
    var first = rides[0];
    dom.routeSay.textContent = t('routeBus', {
      lines: tripLines(rides),
      time: first.at,
      stop: first.from,
      min: Math.max(1, Math.round(trip.seconds / 60))
    });

    dom.routeTrips.textContent = '';
    routeTrips.forEach(function (other, i) {
      var press = el('button', {
        type: 'button',
        className: 'route-trip',
        'aria-pressed': String(i === n),
        textContent: tripRides(other)[0].at + ' · ' + tripLines(tripRides(other))
      });
      press.addEventListener('click', function () {
        TTBTrack.event('route_trip', { n: i });
        drawTrip(i);
      });
      dom.routeTrips.appendChild(press);
    });
    dom.routeTrips.hidden = routeTrips.length < 2;
    if (routeLine.getLayers().length) fitRoute();
  }

  function tripRides(trip) {
    return trip.legs.filter(function (leg) { return leg.name !== undefined; });
  }

  function tripLines(rides) {
    return rides.map(function (leg) { return leg.name || '?'; }).join(' → ');
  }

  function clearRouteLine() {
    if (routeLine) { map.removeLayer(routeLine); routeLine = null; }
    dom.routeTrips.hidden = true;
    dom.routeTrips.textContent = '';
  }

  function clearRoute() {
    routeToken++;
    routeFor = null;
    routeTrips = null;
    clearRouteLine();
    dom.routeBar.hidden = true;
    document.body.classList.remove('route-on');
  }

  function paintShare() {
    var place = state.view === 'detail' && state.selected ? byId(state.selected) : null;
    dom.panelShare.hidden = !place || !!place.standIn;
    if (dom.panelShare.hidden) return;
    dom.panelShare.setAttribute('aria-label', t('listsShare'));
    dom.panelShare.setAttribute('title', t('listsShare'));
  }

  function pressShare() {
    var place = state.view === 'detail' && state.selected ? byId(state.selected) : null;
    if (!place) return;
    var url = window.location.origin + '/?spot=' + encodeURIComponent(place.id) + '&from=share';

    if (navigator.share && window.matchMedia && window.matchMedia('(pointer: coarse)').matches) {
      TTBTrack.event('place_share', { place: place.name, method: 'sheet' });
      navigator.share({ title: place.name, url: url })
        .catch(function () { /* dismissed, which is fine */ });
      return;
    }
    TTBTrack.event('place_share', { place: place.name, method: 'copy' });
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(url)
        .then(function () { toast(t('listsCopied')); })
        .catch(function () { window.prompt(t('listsShare'), url); });
      return;
    }
    window.prompt(t('listsShare'), url);
  }

  var TURNSTILE_URL = 'https://challenges.cloudflare.com/turnstile/v0/api.js' +
                      '?render=explicit&onload=ttbTurnstileReady';
  var turnstileKey = '';
  var turnstileWidget = null;
  var turnstileLoading = null;
  var turnstileWaiting = null;

  function readTurnstileKey() {
    var meta = document.querySelector('meta[name="turnstile-key"]');
    turnstileKey = (meta && meta.getAttribute('content') || '').trim();
  }

  function loadTurnstile() {
    if (turnstileWidget !== null) return Promise.resolve(turnstileWidget);
    if (turnstileLoading) return turnstileLoading;

    turnstileLoading = new Promise(function (resolve, reject) {
      var box = el('div', { className: 'turnstile-box' });
      document.body.appendChild(box);

      window.ttbTurnstileReady = function () {
        try {
          turnstileWidget = window.turnstile.render(box, {
            sitekey: turnstileKey,
            size: 'invisible',
            callback: function (token) { settleTurnstile(token); },
            'error-callback': function () { settleTurnstile(''); },
            'expired-callback': function () { settleTurnstile(''); }
          });
          resolve(turnstileWidget);
        } catch (e) { reject(e); }
      };

      var tag = document.createElement('script');
      tag.src = TURNSTILE_URL;
      tag.async = true;
      tag.defer = true;
      tag.onerror = function () { reject(new Error('turnstile unreachable')); };
      document.head.appendChild(tag);
    });

    return turnstileLoading;
  }

  function settleTurnstile(token) {
    var waiting = turnstileWaiting;
    turnstileWaiting = null;
    if (waiting) waiting(token || '');
  }

  function saveToken() {
    if (!turnstileKey) return Promise.resolve('');
    return loadTurnstile().then(function (id) {
      return new Promise(function (resolve) {
        var done = false;
        turnstileWaiting = function (token) {
          if (done) return;
          done = true;
          resolve(token);
        };
        window.setTimeout(function () {
          if (!done) { done = true; turnstileWaiting = null; resolve(''); }
        }, 6000);
        try {
          window.turnstile.reset(id);
          window.turnstile.execute(id);
        } catch (e) { settleTurnstile(''); }
      });
    }).catch(function () { return ''; });
  }

  var saveBusy = false;

  function pressSave() {
    var place = state.selected ? byId(state.selected) : null;
    if (!place || saveBusy) return;

    var wasSaved = isSaved(place.id);
    var wasCount = saveCount(place.id);
    var on = !wasSaved;

    function revert() {
      markSaved(place.id, wasSaved);
      state.saves[place.id] = wasCount;
      paintSave();
    }

    markSaved(place.id, on);
    state.saves[place.id] = Math.max(0, wasCount + (on ? 1 : -1));
    paintSave();

    dom.panelSave.classList.remove('is-beating');
    void dom.panelSave.offsetWidth;
    dom.panelSave.classList.add('is-beating');

    saveBusy = true;
    saveToken().then(function (token) {
      return fetch('/api/saves', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
          place: place.id,
          client: TTBDevice.id(),
          on: on,
          token: token
        })
      });
    }).then(function (res) {
      return res.json().catch(function () { return {}; }).then(function (out) {
        return { ok: res.ok, out: out || {} };
      });
    }).then(function (answer) {
      if (!answer.ok) {
        revert();
        if (typeof answer.out.n === 'number') state.saves[place.id] = answer.out.n;
        paintSave();
        toast(t(answer.out.error === 'capped' ? 'saveCapped' : 'saveFailed'));
        return;
      }
      if (typeof answer.out.n === 'number') state.saves[place.id] = answer.out.n;
      paintSave();
      syncSavedFilter(on);
      TTBTrack.event(on ? 'save_place' : 'unsave_place', {
        place_id: place.id,
        place: place.name,
        saves_total: saveCount(place.id)
      });
      if (on) showNudge();
    }).catch(function () {
      revert();
      toast(t('saveFailed'));
    }).then(function () {
      saveBusy = false;
    });
  }

  function syncSavedFilter(on) {
    if (savedCount() === (on ? 1 : 0)) paintAccountButton();
    if (state.active.indexOf(SAVED_FILTER) === -1) return;
    if (!savedCount()) state.active.splice(state.active.indexOf(SAVED_FILTER), 1);
    applyFilters();
  }

  var ACCOUNT_URL = '/api/account';

  var NUDGE_KEY = 'ttb.nudged';
  var NUDGE_QUIET = 14 * 24 * 3600 * 1000;
  var nudgedThisVisit = false;
  var nudgeTimer = null;

  function nudgeWelcome() {
    if (nudgedThisVisit) return false;
    if (!state.account.ready || state.account.user) return false;
    var last = parseInt(storeGet(NUDGE_KEY) || '0', 10);
    if (last && Date.now() - last < NUDGE_QUIET) return false;
    return true;
  }

  function showNudge() {
    if (!nudgeWelcome()) return;
    nudgedThisVisit = true;

    dom.nudgeSay.textContent = t('nudgeSay');
    dom.nudgeGo.textContent = t('accountCreate');
    dom.nudgeNo.textContent = t('nudgeLater');
    dom.nudge.hidden = false;

    window.clearTimeout(nudgeTimer);
    nudgeTimer = window.setTimeout(function () {
      TTBTrack.event('account_nudge_faded');
      hideNudge();
    }, 9000);
    TTBTrack.event('account_nudge_shown');
  }

  function hideNudge() {
    window.clearTimeout(nudgeTimer);
    dom.nudge.hidden = true;
  }

  function accountPost(payload) {
    return fetch(ACCOUNT_URL, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(payload)
    }).then(function (res) {
      return res.json().catch(function () { return {}; }).then(function (out) {
        return { ok: res.ok, out: out || {} };
      });
    });
  }

  var accountAnswered = false;

  function accountSettled() {
    if (accountAnswered) return;
    accountAnswered = true;
    if (railWaiting) { railWaiting = false; introduceRail(); }
  }

  function loadAccount() {
    return fetch(ACCOUNT_URL, { headers: { accept: 'application/json' } })
      .then(function (res) { return res.ok ? res.json() : null; })
      .then(function (out) {
        if (!out) { accountSettled(); return; }
        state.account = {
          ready: !!out.ready,
          google: !!out.google,
          user: out.user || null,
          linked: !!out.linked,
          password: out.user ? !!out.password : true
        };
        if (out.user && Array.isArray(out.saved)) adoptSaved(out.saved);
        paintAccountButton();
        paintListsButton();
        if (state.list && state.view === 'list') renderList();
        if (!out.user && state.view === 'detail' && state.selected) {
          var open = byId(state.selected);
          if (open && liveDealFor(open)) renderDetail(open);
        }
        accountSettled();
        openAskedAccount();
        answerGoogle();
        if (accountDeleted) { accountDeleted = false; toast(t('accountDeleteDone')); }
      })
      .catch(function () { /* signed out is a fine place to be */ accountSettled(); });
  }

  function adoptSaved(list) {
    state.saved = keptSaves(list);
    storeSet(SAVED_KEY, JSON.stringify(state.saved));
    seatSaved();
    paintSave();
    paintAccountButton();
    if (state.view === 'list' && dom.panel.classList.contains('is-open')) renderList();
  }

  function paintAccountButton() {
    if (!dom.btnAccount) return;
    var wasHidden = dom.btnAccount.hidden;
    dom.btnAccount.hidden = !state.account.ready && !savedCount();
    if (dom.btnAccount.hidden !== wasHidden) placeRail();
    if (dom.btnAccount.hidden) return;
    var name = state.account.user;
    dom.accountLabel.textContent = name || t('accountOpen');
    dom.btnAccount.setAttribute('aria-label', name ? t('accountSignedIn', { name: name }) : t('accountOpen'));
    dom.btnAccount.setAttribute('title', name ? t('accountSignedIn', { name: name }) : t('accountOpen'));
    dom.btnAccount.classList.toggle('is-on', !!name);

    if (wasHidden && railIntroduced) openHint('account', 0);
  }

  function paintListsButton() {
    if (!dom.btnLists) return;
    var wasHidden = dom.btnLists.hidden;
    dom.btnLists.hidden = !state.account.ready;
    if (dom.btnLists.hidden !== wasHidden) placeRail();
    if (!dom.btnLists.hidden && wasHidden && railIntroduced) openHint('lists', 0);
  }

  var accountAsked = '';
  var accountThen = '';

  var ACCOUNT_PAGE = '/account.html';

  var ACCOUNT_VIEWS = ['in', 'up', 'me', 'password', 'username', 'delete', 'google'];

  var ACCOUNT_STEPS = ['password', 'username', 'delete'];

  var googleSaid = '';
  var accountDeleted = false;
  var GOOGLE_SAID = ['in', 'name', 'linked', 'taken', 'failed'];

  function readAccountLink(params) {
    var said = params.get('google') || '';
    if (GOOGLE_SAID.indexOf(said) !== -1) googleSaid = said;
    accountDeleted = params.get('deleted') === '1';

    var view = params.get('account') || '';
    if (ACCOUNT_VIEWS.indexOf(view) === -1) return;
    accountAsked = view;

    accountThen = samePlace(params.get('then') || '');
  }

  function samePlace(raw) {
    var candidate = String(raw)
      .replace(/^[\u0000-\u0020]+|[\u0000-\u0020]+$/g, '')  /* the browser trims these */
      .replace(/[\t\n\r]/g, '');                            /* and deletes these */
    if (candidate.charAt(0) !== '/') return '';

    var url;
    try { url = new URL(candidate, window.location.origin); }
    catch (e) { return ''; }
    if (url.origin !== window.location.origin) return '';

    return url.pathname + url.search + url.hash;
  }

  function openAskedAccount() {
    if (!accountAsked || !state.account.ready) return;
    var view = accountAsked;
    accountAsked = '';
    if (!state.account.user) {
      if (view !== 'up' && view !== 'google') view = 'in';
    } else if (ACCOUNT_STEPS.indexOf(view) === -1) {
      window.location.href = ACCOUNT_PAGE;
      return;
    }
    openAccount(view, '', 'link');
  }

  function answerGoogle() {
    if (!googleSaid) return;
    var said = googleSaid;
    googleSaid = '';

    if (said === 'name') { openAccount('google', '', 'google'); return; }

    if (said === 'in') {
      TTBTrack.event('account_login', { via: 'google' });
      if (state.account.user) toast(t('accountSignedIn', { name: state.account.user }));
      return;
    }

    if (said === 'linked') { toast(t('accountGoogleLinked')); return; }

    var err = said === 'taken' ? 'accountErrGoogleTaken' : 'accountErrGoogle';
    if (state.account.user) { toast(t(err)); return; }
    openAccount('in', '', 'google');
    accountErr = t(err);
    renderAccount();
  }

  function returnAfterAccount() {
    if (!accountThen) return false;
    var back = accountThen;
    accountThen = '';
    window.location.href = back;
    return true;
  }

  var accountView = 'in';
  var SIGN_VIEWS = ['up', 'in', 'google'];
  var accountBusy = false;
  var accountNote = '';
  var accountErr = '';

  function openAccount(view, note, from) {
    var arriving = dom.accountScrim.hidden;
    if (arriving) state.lastFocus = document.activeElement;
    accountView = view || 'in';
    accountNote = note || '';
    accountErr = '';
    hideNudge();
    if (arriving && !state.account.user && SIGN_VIEWS.indexOf(accountView) !== -1) {
      TTBTrack.event('account_sheet_' + accountView);
      TTBTrack.event('account_from_' + (from || 'link'));
    }
    dom.accountScrim.hidden = false;
    document.body.classList.add('has-scrim');
    renderAccount();
    var first = dom.accountCard.querySelector('input')
      || dom.accountCard.querySelector('.menu-row')
      || dom.accountCard.querySelector('.ac-close');
    if (first) first.focus();
  }

  function openMore() {
    state.lastFocus = document.activeElement;
    dom.moreScrim.hidden = false;
    document.body.classList.add('has-scrim');
    renderMore();
    var first = dom.moreCard.querySelector('.menu-row');
    if (first) first.focus();
  }

  function closeMore() {
    dom.moreScrim.hidden = true;
    document.body.classList.remove('has-scrim');
    var back = state.lastFocus;
    state.lastFocus = null;
    if (back && back.focus) back.focus();
  }

  function renderMore() {
    clear(dom.moreCard);
    var close = el('button', {
      type: 'button',
      className: 'panel-close ac-close',
      'aria-label': t('close'),
      html: '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6L6 18"/></svg>'
    });
    close.addEventListener('click', function () {
      TTBTrack.event('more_close');
      closeMore();
    });
    dom.moreCard.appendChild(close);

    function row(id, name, why, href, event, press) {
      var node = el(href ? 'a' : 'button', href
        ? { className: 'menu-row', href: href }
        : { type: 'button', className: 'menu-row' }, [
        el('span', { className: 'menu-say' }, [
          el('span', { className: 'menu-name', textContent: name }),
          el('span', { className: 'menu-why', textContent: why })
        ]),
        el('span', { className: 'menu-go', 'aria-hidden': 'true', html: AC_CHEVRON })
      ]);
      node.addEventListener('click', function () {
        TTBTrack.event(event);
        if (id) postPress('rail', id);
        if (press) press();
      });
      return el('li', { className: 'menu-item' }, [node]);
    }

    var next = nextStyle();
    dom.moreCard.appendChild(el('div', { className: 'ac-form' }, [
      el('p', { className: 'eyebrow ac-eyebrow', textContent: t('wordmark') }),
      el('h2', { className: 'ac-title', textContent: t('moreOpen') }),
      el('p', { className: 'ac-why', textContent: t('moreLine') }),
      el('ul', { className: 'menu' }, [
        row('ask', t('askOpen'), t('askTitle'), '', 'ask_open', function () {
          closeMore();
          openAsk();
        }),
        row('flash', t('flashDoor'), t('flashDoorWhy'), '/flashcard', 'flash_open_rail'),
        row('style', t('styleLabel'), t(styleKey(next)), '', 'style_open', function () {
          setStyle(next);
          renderMore();
        }),
        row('feedback', t('feedbackTitle'), t('feedbackWhy'), '/feedback', 'feedback_open'),
        row('', t('privacyLink'), t('privacyWhy'), '/privacy', 'privacy_open')
      ])
    ]));
  }

  var WHERE_PAUSE = 300;
  var WHERE_MIN_Q = 3;

  var whereNote = '';
  var whereTimer = null;
  var whereInflight = 0;

  function openWhere(why) {
    TTBTrack.event('where_open', { why: why || 'dot' });
    state.lastFocus = document.activeElement;
    whereNote = why ? t(why) : '';
    dom.whereScrim.hidden = false;
    document.body.classList.add('has-scrim');
    renderWhere();
    var field = dom.whereCard.querySelector('input');
    if (field) field.focus();
  }

  function closeWhere() {
    clearTimeout(whereTimer);
    whereTimer = null;
    whereInflight++;
    dom.whereScrim.hidden = true;
    document.body.classList.remove('has-scrim');
    var back = state.lastFocus;
    state.lastFocus = null;
    if (back && back.focus) back.focus();
  }

  function renderWhere() {
    clear(dom.whereCard);
    var close = el('button', {
      type: 'button',
      className: 'panel-close ac-close',
      'aria-label': t('close'),
      html: '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6L6 18"/></svg>'
    });
    close.addEventListener('click', function () {
      TTBTrack.event('where_close');
      closeWhere();
    });
    dom.whereCard.appendChild(close);

    var form = el('form', { className: 'ac-form' });
    form.appendChild(el('p', { className: 'eyebrow ac-eyebrow', textContent: t('wordmark') }));
    form.appendChild(el('h2', { className: 'ac-title', textContent: t('whereTitle') }));
    form.appendChild(el('p', { className: 'ac-why', textContent: t('whereLine') }));
    if (whereNote) form.appendChild(el('p', { className: 'ac-note', role: 'status', textContent: whereNote }));

    var field = accountField('where-q', 'whereLabel', 'text', { autocomplete: 'off' });
    var input = field.querySelector('input');
    var hint = el('p', { className: 'ac-hint', role: 'status', hidden: true });
    var rows = el('ul', { className: 'menu', hidden: true });
    form.appendChild(field);
    form.appendChild(hint);
    form.appendChild(rows);

    var hits = [];

    function say(key) {
      hint.textContent = key ? t(key) : '';
      hint.hidden = !key;
    }

    function draw(list) {
      clear(rows);
      hits = list;
      rows.hidden = !list.length;
      list.forEach(function (hit) {
        var node = el('button', { type: 'button', className: 'menu-row' }, [
          el('span', { className: 'menu-say' }, [
            el('span', { className: 'menu-name', textContent: hit.label }),
            hit.where ? el('span', { className: 'menu-why', textContent: hit.where }) : null
          ]),
          el('span', { className: 'menu-go', 'aria-hidden': 'true', html: AC_CHEVRON })
        ]);
        node.addEventListener('click', function () { takeWhere(hit); });
        rows.appendChild(el('li', { className: 'menu-item' }, [node]));
      });
    }

    function lookUp(q) {
      var mine = ++whereInflight;
      getJSON('/api/geocode?q=' + encodeURIComponent(q)).then(function (a) {
        return a && Array.isArray(a.results) ? a.results : [];
      }, function (err) {
        return /HTTP 429/.test(err && err.message) ? null : [];
      }).then(function (list) {
        if (mine !== whereInflight) return;
        if (list === null) { draw([]); say('whereBusy'); return; }
        draw(list);
        say(list.length ? '' : 'whereNone');
      });
    }

    input.addEventListener('input', function () {
      clearTimeout(whereTimer);
      var q = input.value.replace(/\s+/g, ' ').trim();
      if (q.length < WHERE_MIN_Q) {
        whereInflight++;
        draw([]);
        say('');
        return;
      }
      whereTimer = setTimeout(function () { lookUp(q); }, WHERE_PAUSE);
    });

    form.addEventListener('submit', function (ev) {
      ev.preventDefault();
      if (hits.length) takeWhere(hits[0]);
    });

    if (navigator.geolocation) {
      var device = el('button', { type: 'button', className: 'alt', textContent: t('whereDevice') });
      device.addEventListener('click', function () {
        TTBTrack.event('where_device');
        closeWhere();
        askDevice();
      });
      form.appendChild(device);
    }

    dom.whereCard.appendChild(form);
  }

  function takeWhere(hit) {
    TTBTrack.event('where_pick');
    closeWhere();
    drawHere(L.latLng(hit.lat, hit.lng), 0, false, false);
  }

  function closeAccount() {
    if (!dom.accountScrim.hidden && !state.account.user && SIGN_VIEWS.indexOf(accountView) !== -1) {
      TTBTrack.event('account_leave_' + accountView);
      if (accountErr) TTBTrack.event('account_left_err', { view: accountView });
    }
    dom.accountScrim.hidden = true;
    document.body.classList.remove('has-scrim');
    var back = state.lastFocus;
    state.lastFocus = null;
    if (back && document.contains(back) && back.focus) back.focus();
  }

  var TOUR_STEPS = [
    { key: 'explainPin', at: nearestPin },
    { key: 'explainList', at: function () {
        return dom.btnList.offsetParent
          ? dom.btnList
          : (dom.list.querySelector('.search-field') || dom.panel);
      } },
    { key: 'explainLang', at: function () { return dom.langSwitch; } },
    { key: 'explainRadio', at: function () { return dom.btnRadio; },
      when: function () { return !dom.btnRadio.hidden; },
      pills: function () { return [dom.btnRadio]; } },
    { key: 'explainChips', drawer: true,
      at: function () { return chipRow() || dom.btnFilters; } },
    { key: 'explainRandom', at: function () { return dom.btnRandom; },
      pills: function () { return [dom.btnRandom]; } },
    { key: 'explainAsk', at: function () { return dom.btnAsk; },
      when: function () { return !shortRail(); },
      pills: function () { return [dom.btnAsk]; } },
    { key: 'explainSave', at: function () { return dom.btnAccount; },
      when: function () { return !dom.btnAccount.hidden; },
      pills: function () { return [dom.btnAccount]; } },
    { key: 'explainLists', at: function () { return dom.btnLists; },
      when: function () { return !dom.btnLists.hidden; },
      pills: function () { return [dom.btnLists]; } },
    { key: 'explainMore', at: function () { return dom.btnMore; },
      when: shortRail,
      pills: function () { return [dom.btnMore]; } },
    { key: 'explainDiscount', when: anyLiveDeal, drawer: true,
      at: function () {
        var row = chipRow();
        return row ? row.children[1] : dom.btnFilters;
      } }
  ];
  var tour = { steps: [], i: -1, press: null, roll: null, slide: null, lit: [] };

  function nearestPin() {
    var pins = dom.map.querySelectorAll('.leaflet-marker-icon');
    var cx = window.innerWidth / 2;
    var cy = window.innerHeight / 2;
    var best = null;
    var bestD = Infinity;
    for (var i = 0; i < pins.length; i++) {
      var r = pins[i].getBoundingClientRect();
      if (!r.width || r.right < 0 || r.bottom < 0 ||
          r.left > window.innerWidth || r.top > window.innerHeight) continue;
      var dx = r.left + r.width / 2 - cx;
      var dy = r.top + r.height / 2 - cy;
      if (dx * dx + dy * dy < bestD) { bestD = dx * dx + dy * dy; best = pins[i]; }
    }
    return best;
  }

  function openExplain() {
    if (!dom.tour || tour.i >= 0) return;
    if (welcomeOwed && dom.welcome && !dom.welcome.hidden) { dismissWelcome(true); return; }
    TTBTrack.event('explain_open');
    if (dom.panel.classList.contains('is-open')) {
      if (isNarrow()) closePanel({ band: false });
      else if (state.view !== 'list') restOnList();
    }
    closeHints();
    tour.steps = [];
    for (var k = 0; k < TOUR_STEPS.length; k++) {
      if (!TOUR_STEPS[k].when || TOUR_STEPS[k].when()) tour.steps.push(TOUR_STEPS[k]);
    }
    state.lastFocus = document.activeElement;
    dom.tour.hidden = false;
    dom.tour.classList.add('no-move');
    var from = dom.welcomeTour.getBoundingClientRect();
    moveCursor(from.left + from.width / 2, from.top + from.height / 2);
    void dom.tour.offsetWidth;
    dom.tour.classList.remove('no-move');
    window.addEventListener('resize', placeTourStep);
    showStep(0);
  }

  function closeExplain() {
    if (tour.i < 0) return;
    tour.i = -1;
    litPills([]);
    tourDrawer(false);
    clearTimeout(tour.press);
    dom.tourCursor.classList.remove('is-click');
    dom.tour.hidden = true;
    window.removeEventListener('resize', placeTourStep);
    var back = state.lastFocus;
    state.lastFocus = null;
    if (back && document.contains(back) && back.focus) back.focus();
  }

  function showStep(i) {
    if (i >= tour.steps.length) { closeExplain(); return; }
    tour.i = i;
    var step = tour.steps[i];
    litPills(step.pills ? step.pills() : []);
    dom.tourSay.textContent = t(step.key);
    var last = i === tour.steps.length - 1;
    dom.tourNext.textContent = t(last ? 'explainClose' : 'explainNext');
    dom.tourSkip.hidden = last;
    clear(dom.tourDots);
    for (var d = 0; d < tour.steps.length; d++) {
      dom.tourDots.appendChild(el('i', { className: d === i ? 'is-on' : '' }));
    }
    placeTourStep();
    tourDrawer(step.drawer);
    dom.tourNext.focus();
  }

  function tourDrawer(want) {
    window.clearTimeout(tour.roll);
    if (!want) { hideChipRow(); return; }
    showChipRow();
    tour.roll = window.setTimeout(placeTourStep, CHIP_ROLL_MS);
  }

  function litPills(pills) {
    window.clearTimeout(tour.slide);
    for (var i = 0; i < tour.lit.length; i++) tour.lit[i].classList.remove('hint-open');
    tour.lit = pills;
    for (var j = 0; j < pills.length; j++) pills[j].classList.add('hint-open');
    if (pills.length) tour.slide = window.setTimeout(placeTourStep, PILL_SLIDE_MS);
  }

  function moveCursor(x, y) {
    clearTimeout(tour.press);
    dom.tourCursor.classList.remove('is-click');
    dom.tourCursor.style.transform = 'translate(' + Math.round(x - 16) + 'px,' + Math.round(y - 6) + 'px)';
    tour.press = setTimeout(function () { dom.tourCursor.classList.add('is-click'); }, 800);
  }

  function placeTourStep() {
    if (tour.i < 0) return;
    var vw = window.innerWidth;
    var vh = window.innerHeight;
    var target = tour.steps[tour.i].at();
    var r = target ? target.getBoundingClientRect() : null;
    if (r && (!r.width || r.bottom < 0 || r.top > vh)) r = null;
    var ring = dom.tourRing;
    var bubble = dom.tourBubble;
    var bw = bubble.offsetWidth;
    var bh = bubble.offsetHeight;
    var bx, by;
    if (r) {
      var left = Math.max(r.left, 8);
      var right = Math.min(r.right, vw - 8);
      var pad = 5;
      ring.hidden = false;
      ring.style.width = Math.round(right - left + pad * 2) + 'px';
      ring.style.height = Math.round(r.height + pad * 2) + 'px';
      ring.style.transform = 'translate(' + Math.round(left - pad) + 'px,' + Math.round(r.top - pad) + 'px)';
      var beside = right < vw / 3 && right + 16 + bw <= vw - 12;
      if (beside) by = Math.min(Math.max(30, r.top + r.height / 2 - bh / 2), vh - bh - 12);
      else if (r.bottom + 34 + bh <= vh - 12) by = r.bottom + 34;
      else if (r.top - 14 - bh >= 30) by = r.top - 14 - bh;
      else by = Math.min(Math.max(30, r.top + r.height / 2 - bh / 2), vh - bh - 12);
      bx = beside ? right + 16 : (left + right) / 2 - bw / 2;
      bx = Math.min(Math.max(12, bx), vw - bw - 12);
      moveCursor(Math.min(left + (right - left) * .6, right - 8), r.top + r.height * .62);
    } else {
      ring.hidden = true;
      bx = (vw - bw) / 2;
      by = (vh - bh) / 2;
      moveCursor(bx + bw - 44, by - 8);
    }
    bubble.style.transform = 'translate(' + Math.round(bx) + 'px,' + Math.round(by) + 'px)';
  }

  function accountField(id, labelKey, type, opts) {
    opts = opts || {};
    var kids = [
      el('span', { className: 'ac-label', textContent: t(labelKey) }),
      el('input', {
        id: id,
        type: type,
        autocomplete: opts.autocomplete || 'off',
        autocapitalize: 'none',
        autocorrect: 'off',
        spellcheck: 'false',
        inputmode: opts.inputmode || null,
        maxlength: opts.maxlength || null
      })
    ];
    if (opts.hint) kids.push(el('span', { className: 'ac-hint', textContent: opts.hint }));
    return el('label', { className: 'ac-field' }, kids);
  }

  function accountValue(id) {
    var node = dom.accountCard.querySelector('#' + id);
    return node ? node.value.trim() : '';
  }

  function accountValues() {
    var pass = dom.accountCard.querySelector('#ac-pass');
    var current = dom.accountCard.querySelector('#ac-current');
    return {
      username: accountValue('ac-user'),
      password: pass ? pass.value : '',
      current: current ? current.value : ''
    };
  }

  function accountSubmit(labelKey, run) {
    var btn = el('button', {
      type: 'submit',
      className: 'go',
      textContent: t(accountBusy ? 'accountWorking' : labelKey),
      disabled: accountBusy || null
    });
    return btn;
  }

  function accountSwitch(labelKey, view) {
    var link = el('button', { type: 'button', className: 'alt', textContent: t(labelKey) });
    link.addEventListener('click', function () {
      TTBTrack.event('account_switch', { view: view });
      openAccount(view);
    });
    return link;
  }

  var ACCOUNT_ERRORS = {
    taken: 'accountErrTaken',
    'no-match': 'accountErrNoMatch',
    password: 'accountErrPassword',
    username: 'accountErrUsername',
    'slow-down': 'accountErrSlow',
    current: 'accountErrCurrent',
    same: 'accountErrSame',
    'same-name': 'accountErrSameName',
    'signed-out': 'accountErrSignedOut',
    'no-pending': 'accountErrGooglePending',
    linked: 'accountErrGoogleTaken',
    'needs-password': 'accountErrNeedsPassword',
    confirm: 'accountErrDeleteConfirm'
  };

  function accountFail(out) {
    if (!state.account.user && SIGN_VIEWS.indexOf(accountView) !== -1) TTBTrack.refused(out, accountView);
    accountErr = t(ACCOUNT_ERRORS[out && out.error] || 'accountErrGeneric');
    accountBusy = false;
    renderAccount();
  }

  function renderAccount() {
    clear(dom.accountCard);

    var close = el('button', {
      type: 'button',
      className: 'panel-close ac-close',
      'aria-label': t('close'),
      html: '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6L6 18"/></svg>'
    });
    close.addEventListener('click', function () {
      TTBTrack.event('account_close');
      closeAccount();
    });
    dom.accountCard.appendChild(close);

    var form = el('form', { className: 'ac-form' });
    form.addEventListener('submit', function (ev) { ev.preventDefault(); });
    dom.accountCard.appendChild(form);

    form.appendChild(el('p', { className: 'eyebrow ac-eyebrow', textContent: t('accountOpen') }));

    if (accountView === 'password') return renderAccountPassword(form);
    if (accountView === 'username') return renderAccountUsername(form);
    if (accountView === 'delete') return renderAccountDelete(form);
    if (accountView === 'google') return renderAccountGoogle(form);
    return renderAccountAuth(form);
  }

  function accountMessages(form) {
    if (accountErr) form.appendChild(el('p', { className: 'ac-err', role: 'alert', textContent: accountErr }));
    if (accountNote) form.appendChild(el('p', { className: 'ac-note', role: 'status', textContent: accountNote }));
  }

  function accountBack() {
    var link = TTBTrack.click(el('a', { className: 'alt ac-back', href: ACCOUNT_PAGE, textContent: t('accountBack') }), 'account_page');
    link.insertBefore(el('span', {
      className: 'ac-back-ico',
      'aria-hidden': 'true',
      html: '<svg viewBox="0 0 24 24" focusable="false"><path d="M15 5l-7 7 7 7"/></svg>'
    }), link.firstChild);
    return link;
  }

  function accountWarn(words) {
    return el('p', { className: 'ac-warn', role: 'note' }, [
      el('span', { className: 'ac-warn-ico', 'aria-hidden': 'true', html:
        '<svg viewBox="0 0 24 24" focusable="false"><path d="M12 3.5 21 19.5H3z"/>' +
        '<path d="M12 10v4"/><circle cx="12" cy="16.7" r=".9"/></svg>' }),
      el('span', { textContent: words })
    ]);
  }

  var AC_CHEVRON = '<svg viewBox="0 0 24 24" focusable="false"><path d="M9 5l7 7-7 7"/></svg>';

  function savedRow() {
    var row = el('button', { type: 'button', className: 'menu-row' }, [
      el('span', { className: 'menu-say' }, [
        el('span', { className: 'menu-name', textContent: t('listSaved') }),
        el('span', { className: 'menu-why', textContent: t('accountSavedWhy') })
      ]),
      el('span', { className: 'menu-go', 'aria-hidden': 'true', html: AC_CHEVRON })
    ]);
    row.addEventListener('click', function () {
      TTBTrack.event('saved_open');
      closeAccount();
      forgetList();
      state.active = [SAVED_FILTER];
      applyFilters({ id: SAVED_FILTER, on: true });
      showList(true);
    });
    return el('li', { className: 'menu-item' }, [row]);
  }

  function renderAccountAuth(form) {
    if (!state.account.ready) {
      form.appendChild(el('ul', { className: 'menu' }, [savedRow()]));
      return;
    }

    var creating = accountView === 'up';
    form.appendChild(el('h2', {
      className: 'ac-title',
      textContent: t(creating ? 'accountCreate' : 'accountSignIn')
    }));
    form.appendChild(el('p', { className: 'ac-why', textContent: t('accountWhy') }));

    if (savedCount()) form.appendChild(el('ul', { className: 'menu' }, [savedRow()]));

    accountMessages(form);

    if (state.account.google) {
      form.appendChild(googleGo());
      form.appendChild(googleOr());
    }

    form.appendChild(accountField('ac-user', 'accountUsername', 'text', {
      autocomplete: 'username',
      maxlength: '24',
      hint: creating ? t('accountUsernameHint') : ''
    }));
    form.appendChild(accountField('ac-pass', 'accountPassword', 'password', {
      autocomplete: creating ? 'new-password' : 'current-password'
    }));

    if (creating) form.appendChild(accountWarn(t('accountNoReset')));

    if (creating) {
      form.appendChild(el('p', { className: 'ac-why' }, [
        TTBTrack.click(el('a', { href: '/privacy', textContent: t('privacySignup') }), 'privacy_open', { from: 'signup' })
      ]));
    }

    var go = accountSubmit(creating ? 'accountCreate' : 'accountSignIn');
    go.addEventListener('click', function () {
      if (accountBusy) return;
      var v = accountValues();
      accountBusy = true; accountErr = ''; renderAccount();
      TTBTrack.event('account_try_' + (creating ? 'up' : 'in'));
      accountPost({
        action: creating ? 'create' : 'login',
        username: v.username,
        password: v.password,
        client: TTBDevice.id()
      }).then(function (a) {
        accountBusy = false;
        if (!a.ok) return accountFail(a.out);
        state.account.user = a.out.user;
        if (Array.isArray(a.out.saved)) adoptSaved(a.out.saved);
        paintAccountButton();
        TTBTrack.event(creating ? 'account_create' : 'account_login', {});
        TTBTrack.event('account_done_' + (creating ? 'up' : 'in'));
        closeAccount();
        if (returnAfterAccount()) return;
        toast(t('accountSignedIn', { name: a.out.user }));
      }).catch(function () { accountFail({ error: 'network' }); });
    });
    form.appendChild(go);

    form.appendChild(accountSwitch(creating ? 'accountSwitchSignIn' : 'accountSwitchCreate',
                                   creating ? 'in' : 'up'));
  }

  var GOOGLE_MARK =
    '<svg viewBox="0 0 48 48" focusable="false">' +
    '<path fill="#4285F4" d="M45.12 24.5c0-1.56-.14-3.06-.4-4.5H24v8.51h11.84c-.51 2.75-2.06 5.08-4.39 6.64v5.52h7.11c4.16-3.83 6.56-9.47 6.56-16.17z"/>' +
    '<path fill="#34A853" d="M24 46c5.94 0 10.92-1.97 14.56-5.33l-7.11-5.52c-1.97 1.32-4.49 2.1-7.45 2.1-5.73 0-10.58-3.87-12.31-9.07H4.34v5.7C7.96 41.07 15.4 46 24 46z"/>' +
    '<path fill="#FBBC05" d="M11.69 28.18C11.25 26.86 11 25.45 11 24s.25-2.86.69-4.18v-5.7H4.34C2.85 17.09 2 20.45 2 24s.85 6.91 2.34 9.88l7.35-5.7z"/>' +
    '<path fill="#EA4335" d="M24 10.75c3.23 0 6.13 1.11 8.41 3.29l6.31-6.31C34.91 4.18 29.93 2 24 2 15.4 2 7.96 6.93 4.34 14.12l7.35 5.7c1.73-5.2 6.58-9.07 12.31-9.07z"/>' +
    '</svg>';

  function googleThen() {
    if (accountThen) return accountThen;
    var params = new URLSearchParams(window.location.search);
    params.delete('account');
    params.delete('then');
    params.delete('google');
    var query = params.toString();
    return window.location.pathname + (query ? '?' + query : '');
  }

  function googleHref() {
    var device = TTBDevice.known();
    return '/api/google?then=' + encodeURIComponent(googleThen()) +
      (device ? '&client=' + encodeURIComponent(device) : '');
  }

  function googleGo() {
    return TTBTrack.click(
      el('a', { className: 'ac-google', href: googleHref() }, [
        el('span', { className: 'ac-google-mark', 'aria-hidden': 'true', html: GOOGLE_MARK }),
        el('span', { textContent: t('accountGoogle') })
      ]),
      'account_google', { view: accountView }
    );
  }

  function googleOr() {
    return el('p', { className: 'ac-or' }, [el('span', { textContent: t('accountOr') })]);
  }

  function renderAccountGoogle(form) {
    form.appendChild(el('h2', { className: 'ac-title', textContent: t('accountGoogleName') }));
    form.appendChild(el('p', { className: 'ac-why', textContent: t('accountGoogleNameWhy') }));

    accountMessages(form);

    form.appendChild(accountField('ac-user', 'accountUsername', 'text', {
      autocomplete: 'username',
      maxlength: '24',
      hint: t('accountUsernameHint')
    }));

    var go = accountSubmit('accountCreate');
    go.addEventListener('click', function () {
      if (accountBusy) return;
      var v = accountValues();
      accountBusy = true; accountErr = ''; renderAccount();
      TTBTrack.event('account_try_google');
      accountPost({ action: 'google-name', username: v.username, client: TTBDevice.id() })
        .then(function (a) {
          accountBusy = false;
          if (!a.ok) return accountFail(a.out);
          state.account.user = a.out.user;
          state.account.linked = true;
          state.account.password = false;
          if (Array.isArray(a.out.saved)) adoptSaved(a.out.saved);
          paintAccountButton();
          TTBTrack.event('account_create', { via: 'google' });
          TTBTrack.event('account_done_google');
          closeAccount();
          if (returnAfterAccount()) return;
          toast(t('accountSignedIn', { name: a.out.user }));
        }).catch(function () { accountFail({ error: 'network' }); });
    });
    form.appendChild(go);
  }

  function renderAccountPassword(form) {
    var setting = !state.account.password;

    form.appendChild(accountBack());
    form.appendChild(el('h2', {
      className: 'ac-title',
      textContent: t(setting ? 'accountSetPassword' : 'accountChange')
    }));
    form.appendChild(el('p', {
      className: 'ac-why',
      textContent: t(setting ? 'accountSetPasswordWhy' : 'accountChangeWhy')
    }));
    accountMessages(form);

    if (!setting) {
      form.appendChild(accountField('ac-current', 'accountCurrentPassword', 'password', {
        autocomplete: 'current-password'
      }));
    }
    form.appendChild(accountField('ac-pass', setting ? 'accountPassword' : 'accountNewPassword', 'password', {
      autocomplete: 'new-password'
    }));
    if (!setting) form.appendChild(accountWarn(t('accountChangeSignsOut')));

    var go = accountSubmit(setting ? 'accountSetPasswordGo' : 'accountChangeGo');
    go.addEventListener('click', function () {
      if (accountBusy) return;
      var v = accountValues();
      accountBusy = true; accountErr = ''; renderAccount();
      accountPost({ action: 'password-change', current: v.current, password: v.password })
        .then(function (a) {
          accountBusy = false;
          if (!a.ok) return accountFail(a.out);
          TTBTrack.event('account_password_change', { setting: setting });
          state.account.password = true;
          closeAccount();
          toast(t(setting ? 'accountSetPasswordDone' : 'accountChangeDone'));
          returnAfterAccount();
        }).catch(function () { accountFail({}); });
    });
    form.appendChild(go);
  }

  function renderAccountUsername(form) {
    form.appendChild(accountBack());
    form.appendChild(el('h2', { className: 'ac-title', textContent: t('accountName') }));
    form.appendChild(el('p', {
      className: 'ac-why',
      textContent: t('accountNameWhy', { name: state.account.user || '' })
    }));
    accountMessages(form);

    form.appendChild(accountField('ac-user', 'accountNewUsername', 'text', {
      autocomplete: 'username',
      maxlength: '24',
      hint: t('accountUsernameHint')
    }));
    if (state.account.password) {
      form.appendChild(accountField('ac-current', 'accountCurrentPassword', 'password', {
        autocomplete: 'current-password'
      }));
    }
    form.appendChild(accountWarn(t('accountNameCosts')));

    var go = accountSubmit('accountNameGo');
    go.addEventListener('click', function () {
      if (accountBusy) return;
      var v = accountValues();
      accountBusy = true; accountErr = ''; renderAccount();
      accountPost({ action: 'username-change', username: v.username, current: v.current })
        .then(function (a) {
          accountBusy = false;
          if (!a.ok) return accountFail(a.out);
          TTBTrack.event('account_rename');
          state.account.user = a.out.user;
          paintAccountButton();
          closeAccount();
          toast(t('accountNameDone', { name: a.out.user }));
          returnAfterAccount();
        }).catch(function () { accountFail({}); });
    });
    form.appendChild(go);
  }

  function renderAccountDelete(form) {
    var hasPassword = !!state.account.password;

    form.appendChild(accountBack());
    form.appendChild(el('h2', { className: 'ac-title', textContent: t('accountDelete') }));
    form.appendChild(el('p', {
      className: 'ac-why',
      textContent: t('accountDeleteWhy', { name: state.account.user || '' })
    }));
    accountMessages(form);

    if (hasPassword) {
      form.appendChild(accountField('ac-current', 'accountCurrentPassword', 'password', {
        autocomplete: 'current-password'
      }));
    } else {
      form.appendChild(accountField('ac-user', 'accountDeleteTypeName', 'text', {
        maxlength: '24',
        hint: state.account.user || ''
      }));
    }
    form.appendChild(accountWarn(t('accountDeleteCosts')));

    var go = accountSubmit('accountDeleteGo');
    go.addEventListener('click', function () {
      if (accountBusy) return;
      var v = accountValues();
      accountBusy = true; accountErr = ''; renderAccount();
      accountPost({ action: 'delete', current: v.current, username: v.username })
        .then(function (a) {
          accountBusy = false;
          if (!a.ok) return accountFail(a.out);
          TTBTrack.event('account_delete');
          storeSet(SAVED_KEY, '[]');
          window.location.href = '/?deleted=1';
        }).catch(function () { accountFail({}); });
    });
    form.appendChild(go);
  }

  var counted = {};

  function postPress(kind, id) {
    if (window.TTBTrack && window.TTBTrack.owner) {
      if (kind !== 'place') return;
      kind = 'venue';
    }
    fetch('/api/stats', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ kind: kind, id: id, device: TTBTrack.device() })
    }).catch(function () { /* the ranking misses one, the map is unaffected */ });
  }

  function countPress(kind, id) {
    var key = kind + '/' + id;
    if (counted[key]) return;
    counted[key] = true;
    postPress(kind, id);
  }

  var RAIL_PRESS = {
    'btn-account': 'account',
    'btn-lists': 'lists',
    'btn-flash': 'flash',
    'btn-random': 'random',
    'btn-ask': 'ask',
    'btn-locate': 'locate',
    'btn-more': 'more',
    'btn-feedback': 'feedback'
  };

  function countRailPress(ev) {
    var node = ev.target;
    var btn = null;
    while (node && node !== dom.rail) {
      if (node.classList && node.classList.contains('rail-btn')) { btn = node; break; }
      node = node.parentNode;
    }
    if (!btn) return;
    var id = RAIL_PRESS[btn.id]
      || (dom.styles && dom.styles.contains(btn) ? 'style' : '');
    if (id) postPress('rail', id);
  }

  function toggleChip(id) {
    forgetResults({ redraw: false });
    forgetAnswer({ redraw: false });
    forgetList();
    var at = state.active.indexOf(id);
    if (at === -1) state.active.push(id); else state.active.splice(at, 1);
    applyFilters({ id: id, on: at === -1 });
  }

  function clearChips() {
    if (!state.active.length && !state.list && !state.answer && !state.results) return;
    forgetResults({ redraw: false });
    forgetAnswer({ redraw: false });
    forgetList();
    state.active = [];
    applyFilters();
  }

  function activeFromUrl(params) {
    if (params.get('saved') === '1' && savedCount()) return [SAVED_FILTER];

    var picked = params.get('type');
    if (!picked) return [];
    var live = usedTypeIds();
    if (anyLiveDeal()) live = live.concat(DEAL_FILTER);
    return picked.split(',').filter(function (id) { return live.indexOf(id) !== -1; });
  }

  function usedTypeIds() {
    var used = {};
    state.places.forEach(function (p) {
      (p.types || []).forEach(function (id) { used[id] = true; });
    });
    return state.types
      .filter(function (t2) { return t2.chip !== false; })
      .map(function (t2) { return t2.id; })
      .filter(function (id) { return used[id]; });
  }

  function anyLiveDeal() {
    return state.places.some(function (p) { return !!liveDealFor(p); });
  }

  function matchesFilters(place) {
    if (state.active.indexOf(SAVED_FILTER) !== -1 && isSaved(place.id)) return true;
    if (place.standIn) return false;
    if (state.active.indexOf(DEAL_FILTER) !== -1 && liveDealFor(place)) return true;
    return (place.types || []).some(function (id) {
      return state.active.indexOf(id) !== -1;
    });
  }

  function visiblePlaces() {
    if (state.results) return resultPlaces();
    if (state.answer) return answerPlaces();
    if (state.list) return allPlaces().filter(function (p) { return isOnList(p.id); });
    if (!state.active.length) return state.places.slice();
    return allPlaces().filter(matchesFilters);
  }

  function answerPlaces() {
    var out = [];
    state.answer.picks.forEach(function (pick) {
      var place = byId(pick.id);
      if (place) out.push(place);
    });
    return out;
  }

  function answerWhy(id) {
    if (!state.answer) return '';
    for (var i = 0; i < state.answer.picks.length; i++) {
      if (state.answer.picks[i].id === id) return state.answer.picks[i].why || '';
    }
    return '';
  }

  var filterOpenTimer = null;
  var CHIP_ROLL_MS = 640;
  var PILL_SLIDE_MS = 380;

  function filterMenuOpen() {
    return dom.filterBar.classList.contains('is-open');
  }

  function setFilterMenu(open) {
    if (open === filterMenuOpen()) return;
    dom.filterBar.classList.toggle('is-open', open);
    dom.btnFilters.setAttribute('aria-expanded', String(open));
    window.clearTimeout(filterOpenTimer);
    if (!open) {
      dom.filterBar.classList.remove('is-opening');
      if (drawerHolds()) clearChips();
      return;
    }
    dom.filterBar.classList.add('is-opening');
    updateFilterFades();
    filterOpenTimer = window.setTimeout(function () {
      dom.filterBar.classList.remove('is-opening');
      updateFilterFades();
    }, CHIP_ROLL_MS);
  }

  function closeFilterMenu() { setFilterMenu(false); }

  function drawerHolds() {
    if (!isNarrow()) return false;
    if (!shortRail()) return state.active.length > 0;
    return state.active.some(function (id) { return FRONT_CHIPS.indexOf(id) === -1; });
  }

  function chipRow() {
    return dom.filters.getBoundingClientRect().width ? dom.filters : null;
  }

  var chipRowShown = false;

  function showChipRow() {
    if (!isNarrow() || filterMenuOpen()) return;
    chipRowShown = true;
    setFilterMenu(true);
  }

  function hideChipRow() {
    if (!chipRowShown) return;
    chipRowShown = false;
    if (!drawerHolds()) setFilterMenu(false);
  }

  function syncFilterMenuToWidth() {
    if (drawerHolds()) setFilterMenu(true);
  }

  function chipEl(label, on, press) {
    var chip = el('button', {
      type: 'button',
      className: 'chip',
      'aria-pressed': String(on),
      textContent: label
    });
    chip.addEventListener('click', press);
    return chip;
  }

  function renderFilters() {
    clear(dom.filters);
    clear(dom.chipsFront);

    dom.filters.appendChild(chipEl(t('filterAll'), state.active.length === 0, clearChips));
    if (state.active.length) dom.chipsFront.appendChild(chipEl(t('filterAll'), false, clearChips));

    var ids = anyLiveDeal() ? [DEAL_FILTER].concat(usedTypeIds()) : usedTypeIds();
    ids.forEach(function (id) {
      var on = state.active.indexOf(id) !== -1;
      var label = id === DEAL_FILTER ? t('filterDiscount') : typeLabel(id);
      var press = function () { toggleChip(id); };
      var chip = dom.filters.appendChild(chipEl(label, on, press));
      if (FRONT_CHIPS.indexOf(id) !== -1) {
        chip.classList.add('chip-front');
        dom.chipsFront.appendChild(chipEl(label, on, press));
      }
    });

    var chips = dom.filters.children;
    for (var c = 0; c < chips.length; c++) {
      chips[c].style.setProperty('--i', String(Math.min(c, 7)));
    }

    updateFilterFades();
  }

  function updateFilterFades() {
    fadeEdges(dom.filters);
    fadeEdges(dom.chipsFront);
  }

  function fadeEdges(box) {
    var max = box.scrollWidth - box.clientWidth;
    var x = box.scrollLeft;
    box.classList.toggle('can-left', max > 1 && x > 1);
    box.classList.toggle('can-right', max > 1 && x < max - 1);
  }

  var CLUSTER_PX = 32;

  var CLUSTER_ZOOM_MAX = 17;

  var CLUSTER_TIERS = [
    { over: 50, label: 50, d: 58 },
    { over: 30, label: 30, d: 52 },
    { over: 20, label: 20, d: 46 },
    { over: 10, label: 10, d: 40 }
  ];

  function clusterTier(count) {
    for (var i = 0; i < CLUSTER_TIERS.length; i++) {
      if (count > CLUSTER_TIERS[i].over) return CLUSTER_TIERS[i];
    }
    return null;
  }

  function clusterCount(count) {
    var tier = clusterTier(count);
    return tier ? tier.label + '+' : String(count);
  }

  function clusterSize(count) {
    var tier = clusterTier(count);
    return tier ? tier.d : 30 + count;
  }

  function pinGroups(places) {
    var zoom = map.getZoom();
    if (zoom > CLUSTER_ZOOM_MAX) {
      return places.map(function (p) { return [{ place: p }]; });
    }
    var pts = places.map(function (p) {
      return { place: p, pt: map.project([p.lat, p.lng], zoom) };
    });
    var taken = [];
    var groups = [];

    pts.forEach(function (seed, i) {
      if (taken[i]) return;
      taken[i] = true;
      var group = [seed];
      pts.forEach(function (other, j) {
        if (j <= i || taken[j]) return;
        if (seed.pt.distanceTo(other.pt) < CLUSTER_PX) {
          taken[j] = true;
          group.push(other);
        }
      });
      groups.push(group);
    });
    return groups;
  }

  function clearClusters() {
    clusterPins.forEach(function (pin) { if (map) map.removeLayer(pin); });
    clusterPins = [];
  }

  function clusterPin(group) {
    var count = group.length;
    var lat = 0;
    var lng = 0;
    group.forEach(function (m) { lat += m.place.lat; lng += m.place.lng; });

    var size = clusterSize(count);
    var shown = clusterCount(count);
    var label = t('clusterLabel', { count: shown });
    var pin = L.marker([lat / count, lng / count], {
      icon: L.divIcon({
        className: 'cluster-pin',
        html: '<span class="cluster-dot' + (count > 2 ? ' is-many' : '') +
              '" style="--cluster-d:' + size + 'px">' +
              '<span class="cluster-count">' + shown + '</span></span>',
        iconSize: [size, size],
        iconAnchor: [size / 2, size / 2]
      }),
      keyboard: true,
      title: label,
      alt: label,
      zIndexOffset: -100
    });

    function breakZoom() {
      var far = 0;
      group.forEach(function (m) { far = Math.max(far, group[0].pt.distanceTo(m.pt)); });
      if (far <= 0) return CLUSTER_ZOOM_MAX + 1;
      return map.getZoom() + Math.ceil(Math.log(CLUSTER_PX / far) / Math.LN2);
    }

    function open() {
      TTBTrack.event('cluster_open', { cluster_size: count });
      var pts = group.map(function (m) { return [m.place.lat, m.place.lng]; });
      var bounds = L.latLngBounds(pts);
      var pad = isNarrow() ? 112 : 220;
      var fit = map.getBoundsZoom(bounds, false, L.point(pad, pad));
      var target = Math.min(
        Math.ceil(Math.max(fit, breakZoom(), map.getZoom() + 1)),
        CLUSTER_ZOOM_MAX + 1
      );
      map.setView(bounds.getCenter(), target, { animate: !reduceMotion() });
    }
    pin.on('click', open);
    pin.on('keypress', function (ev) {
      if (ev.originalEvent && ev.originalEvent.key === 'Enter') open();
    });

    return pin;
  }

  function syncMarkers() {
    if (!map) return;
    var alone = {};
    var pool = [];

    visiblePlaces().forEach(function (p) {
      if (!isLit(p)) pool.push(p);
    });
    if (state.selected) alone[state.selected] = true;
    if (state.marked && byId(state.marked)) alone[state.marked] = true;

    clearClusters();

    pinGroups(pool).forEach(function (group) {
      if (group.length === 1) {
        alone[group[0].place.id] = true;
        return;
      }
      var pin = clusterPin(group);
      pin.addTo(map);
      clusterPins.push(pin);
    });

    allPlaces().forEach(function (p) {
      var marker = markers[p.id];
      if (!marker) return;
      var ring = closedRings[p.id];
      if (alone[p.id]) {
        if (!map.hasLayer(marker)) marker.addTo(map);
        if (ring && !map.hasLayer(ring)) { ring.addTo(map); if (ring.bringToBack) ring.bringToBack(); }
      } else {
        if (map.hasLayer(marker)) map.removeLayer(marker);
        if (ring && map.hasLayer(ring)) map.removeLayer(ring);
      }
    });
    soloPins = alone;
  }

  var dropped = null;

  function forgetList() {
    if (!state.list) return;

    dropped = { list: state.list, places: state.listPlaces };

    var standing = {};
    state.listPlaces.forEach(function (p) { standing[p.id] = true; });
    if (state.selected && standing[state.selected]) {
      state.selected = null;
      state.view = 'list';
    }
    if (state.marked && standing[state.marked]) state.marked = null;

    dropPins(state.listPlaces);
    state.list = null;
    state.listPlaces = [];

    syncUrl(true);
  }

  function restoreList(id) {
    if (!dropped || dropped.list.id !== id) return false;
    state.list = dropped.list;
    state.listPlaces = dropped.places;
    addPins(state.listPlaces);
    dropped = null;
    return true;
  }

  function applyFilters(change) {
    seatSaved();
    if (state.marked && state.marked !== state.selected) {
      var held = byId(state.marked);
      var keeps = !held ? false
        : state.list ? isOnList(held.id)
        : !state.active.length || matchesFilters(held);
      if (!keeps) state.marked = null;
    }
    syncUrl();
    renderFilters();
    if (state.view === 'list') renderPanel();
    paintMarkers();

    var shown = visiblePlaces();
    if (state.active.length && shown.length === 1) refocus(shown[0], true);

    else if (!anyInView(shown)) fitToPins({ animate: true });

    var params = {
      filters: state.active.length ? state.active.slice().sort().join(',') : 'all',
      filter_count: state.active.length,
      places_shown: visiblePlaces().length
    };
    if (change) {
      params.filter_id = change.id;
      params.filter_state = change.on ? 'on' : 'off';
      TTBTrack.event('filter_select', params);
      if (change.on) countPress('filter', change.id);
    } else {
      TTBTrack.event('filter_clear', params);
    }
  }

  function sheetIsOver() {
    return isNarrow() && document.body.classList.contains('panel-open');
  }

  var HINT_MS = 4200;
  var HINT_KEYS = ['account', 'lists', 'flash', 'random', 'more', 'ask',
                   'style', 'locate', 'feedback'];
  var hintTimers = {};

  function railKeys() {
    if (shortRail()) return ['account', 'lists', 'random', 'more', 'locate'];
    return HINT_KEYS.filter(function (key) { return key !== 'more'; });
  }

  var RAIL_IN = 1150;
  var welcomeOwed = false;
  var introPending = false;
  var railIntroduced = false;
  var RAIL_WAIT_MS = 1400;
  var railWaited = false;
  var railWaiting = false;
  var INTRO_KEY = 'ttb.introduced';

  function hintPill(key) {
    if (key === 'account') return dom.btnAccount;
    if (key === 'lists') return dom.btnLists;
    if (key === 'more') return dom.btnMore;
    if (key === 'flash') return dom.btnFlash;
    if (key === 'ask') return dom.btnAsk;
    if (key === 'radio') return dom.btnRadio;
    if (key === 'style') return dom.styles && dom.styles.querySelector('.rail-btn');
    if (key === 'locate') return dom.btnLocate;
    if (key === 'feedback') return dom.btnFeedback;
    return dom.btnRandom;
  }

  function hintText(btn) {
    var label = btn && btn.querySelector('.rail-label');
    return label ? (label.textContent || '').replace(/^\s+|\s+$/g, '') : '';
  }

  function closeHint(key) {
    if (hintTimers[key]) { clearTimeout(hintTimers[key]); hintTimers[key] = null; }
    var btn = hintPill(key);
    if (btn) btn.classList.remove('hint-open');
  }

  function closeHints() {
    closeChipRowHint();
    for (var i = 0; i < HINT_KEYS.length; i++) closeHint(HINT_KEYS[i]);
  }

  function shownPill(btn) {
    return !!(btn && !btn.hidden && btn.getBoundingClientRect().width);
  }

  function openHint(key, delay) {
    var btn = hintPill(key);
    if (!shownPill(btn) || !hintText(btn)) return;
    closeHint(key);
    hintTimers[key] = setTimeout(function () {
      if (btn.hidden || !hintText(btn) || sheetIsOver()) {
        hintTimers[key] = null;
        return;
      }
      btn.classList.add('hint-open');
      hintTimers[key] = setTimeout(function () {
        btn.classList.remove('hint-open');
        hintTimers[key] = null;
      }, HINT_MS);
    }, delay || 0);
  }

  var chipRowTimer = null;

  function closeChipRowHint() {
    if (chipRowTimer) { clearTimeout(chipRowTimer); chipRowTimer = null; }
    hideChipRow();
  }

  function openChipRowHint() {
    closeChipRowHint();
    chipRowTimer = setTimeout(function () {
      if (sheetIsOver()) {
        chipRowTimer = null;
        return;
      }
      showChipRow();
      chipRowTimer = setTimeout(function () {
        chipRowTimer = null;
        hideChipRow();
      }, HINT_MS);
    }, RAIL_IN);
  }

  function introduceRail() {
    if (!isNarrow()) return;
    if (sheetIsOver() || (dom.stories && !dom.stories.hidden)) {
      introPending = true;
      return;
    }
    if (welcomeOwed) {
      introPending = false;
      showWelcome();
      return;
    }
    if (!accountAnswered && !railWaited) {
      railWaited = true;
      railWaiting = true;
      setTimeout(function () {
        if (railWaiting) { railWaiting = false; introduceRail(); }
      }, RAIL_WAIT_MS);
      return;
    }
    railWaiting = false;
    introPending = false;
    railIntroduced = true;
    storeSet(INTRO_KEY, '1');
    var keys = railKeys();
    for (var i = 0; i < keys.length; i++) openHint(keys[i], RAIL_IN + i * 300);
    openChipRowHint();
  }

  function showWelcome() {
    if (!dom.welcome || !dom.welcome.hidden) return;
    dom.welcome.hidden = false;
    requestAnimationFrame(function () {
      requestAnimationFrame(function () { dom.welcome.classList.add('is-up'); });
    });
  }

  function dismissWelcome(tour) {
    if (!welcomeOwed || !dom.welcome || dom.welcome.hidden) return;
    welcomeOwed = false;
    dom.welcome.classList.remove('is-up');
    setTimeout(function () { dom.welcome.hidden = true; }, reduceMotion() ? 0 : 320);
    if (tour) {
      storeSet(INTRO_KEY, '1');
      openExplain();
    } else {
      introduceRail();
    }
  }

  var RAIL_NEAR = 300;
  var RAIL_FAR = 360;
  var hoverMQ = window.matchMedia
    ? window.matchMedia('(min-width: 861px) and (hover: hover) and (pointer: fine)')
    : null;
  function hasHover() { return !!(hoverMQ && hoverMQ.matches); }

  var railNear = false;
  var railShown = false;

  function railFocused() {
    var node = document.activeElement;
    if (!node) return false;
    if (!((dom.rail && dom.rail.contains(node)) ||
          (dom.brand && dom.brand.contains(node)))) return false;
    try { return node.matches(':focus-visible'); }
    catch (err) { return true; }
  }

  function railHovered() {
    return !!((dom.rail && dom.rail.matches(':hover')) ||
              (dom.brand && dom.brand.matches(':hover')));
  }

  function syncRailReveal() {
    var on = hasHover() && (railNear || railHovered() || railFocused());
    if (on === railShown) return;
    railShown = on;
    document.body.classList.toggle('rail-open', on);
  }

  var PEEK_MS = 260;
  var peekTimer = null;
  var peekAt = '';

  function cancelPeek() {
    if (peekTimer) { window.clearTimeout(peekTimer); peekTimer = null; }
    peekAt = '';
  }

  function peekRow(id) {
    if (id === peekAt) return;
    cancelPeek();
    if (!id || id === state.selected) return;
    var place = byId(id);
    if (!place) return;
    peekAt = id;
    peekTimer = window.setTimeout(function () {
      peekTimer = null;
      if (peekAt !== id || document.body.classList.contains('panel-ask')) return;
      focusOn(place, false);
    }, PEEK_MS);
  }

  function wireRowPeek() {
    if (!dom.listBody) return;
    dom.listBody.addEventListener('mouseover', function (ev) {
      if (!hasHover()) return;
      var row = ev.target.closest ? ev.target.closest('.list-row') : null;
      peekRow(row ? row.getAttribute('data-id') : '');
    });
    dom.listBody.addEventListener('mouseleave', cancelPeek);
    dom.listBody.addEventListener('click', cancelPeek);
  }

  function wireRailReveal() {
    if (!dom.rail || !dom.brand) return;
    window.addEventListener('pointermove', function (ev) {
      if (ev.pointerType && ev.pointerType !== 'mouse') return;
      if (ev.clientX <= RAIL_NEAR) railNear = true;
      else if (ev.clientX > RAIL_FAR) railNear = false;
      syncRailReveal();
    }, { passive: true });

    document.addEventListener('focusin', syncRailReveal);
    document.addEventListener('focusout', function () {
      setTimeout(syncRailReveal, 0);
    });
  }

  function mountRadio() {
    window.TTBRadio.mount({
      button: dom.btnRadio,
      name: dom.radioName,
      lang: state.lang,
      t: t,
      onchange: function (what) {
        if (what === 'fail') { closeHint('radio'); toast(t('radioFail')); return; }
        if (what === 'stop') { closeHint('radio'); return; }
        openHint('radio', 0);
      }
    });
  }

  function mountShell() {
    window.TTBShell.mount({
      surface: document.getElementById('shell'),
      onopen: function () { closeMore(); closeAccount(); },
      onclose: function () { loadAccount(); }
    });
  }

  var ROLLED_MS = FLY_MS * 1000;
  var rolledTimer = null;

  function randomPick() {
    var pool = visiblePlaces().filter(function (p) { return !p.closed; });

    if (!pool.length) {
      toast(t('randomNone'));
      return;
    }

    var choice = pool[0];
    if (pool.length > 1) {
      do {
        choice = pool[Math.floor(Math.random() * pool.length)];
      } while (choice.id === state.lastPick);
    }

    state.lastPick = choice.id;
    TTBTrack.event('random_pick', { place: choice.name, pool: pool.length });
    selectPlace(choice.id, { fly: true, withHere: true });
    if (shortRail()) sayRolled();
  }

  function sayRolled() {
    var label = dom.btnRandom.querySelector('.rail-label');
    clearTimeout(rolledTimer);
    label.textContent = t('randomDone');
    dom.btnRandom.classList.add('is-rolled');
    rolledTimer = setTimeout(function () {
      dom.btnRandom.classList.remove('is-rolled');
      rolledTimer = setTimeout(function () {
        rolledTimer = null;
        label.textContent = t('randomPick');
      }, 400);
    }, ROLLED_MS);
  }

  var ASK_URL = '/api/ask';

  var cuisinesLoading = null;

  function loadCuisines() {
    if (!cuisinesLoading) {
      cuisinesLoading = getJSON('data/cuisines.json')
        .then(function (data) { return (data && data.cuisines) || []; })
        .catch(function () { return []; });
    }
    return cuisinesLoading;
  }

  function readWish(question, cuisines) {
    return window.TTBAsk.read(question, {
      fold: fold,
      types: state.types,
      cuisines: cuisines,
      words: {
        cheap: t('askWordsCheap'),
        fancy: t('askWordsFancy'),
        open: t('askWordsOpen'),
        near: t('askWordsNear'),
        me: t('askWordsMe')
      }
    });
  }

  function whereabouts(wish) {
    if (hereMarker) {
      var here = hereMarker.getLatLng();
      return Promise.resolve({ lat: here.lat, lng: here.lng });
    }
    if (!wish.nearby || wish.near) return Promise.resolve(null);
    return locateOnce();
  }

  function locateOnce() {
    return new Promise(function (resolve) {
      if (!map || !navigator.geolocation) { resolve(null); return; }
      var done = function (point) {
        map.off('locationfound', found);
        map.off('locationerror', failed);
        resolve(point);
      };
      var found = function (ev) { done({ lat: ev.latlng.lat, lng: ev.latlng.lng }); };
      var failed = function () { done(null); };
      map.on('locationfound', found);
      map.on('locationerror', failed);
      map.locate({ setView: false, timeout: 8000 });
    });
  }

  function setAsking(on) {
    dom.askForm.classList.toggle('is-asking', on);
  }

  function askSubmit() {
    var question = String(dom.askInput.value || '')
      .slice(0, window.TTBAsk.MAX_QUESTION).trim();
    if (!question) return;

    TTBTrack.event('ask', { search_term: question.toLowerCase() });

    var history = state.asks.filter(function (turn) {
      return !turn.pending;
    }).slice(-10).map(function (turn) {
      return {
        q: turn.q,
        say: turn.say,
        picks: turn.picks.map(function (pick) { return { id: pick.id, why: pick.why }; })
      };
    });

    var turn = {
      q: question, pending: true,
      say: '', picks: [], city: [], open: {}, at: '', source: '', wish: null
    };
    state.asks.push(turn);
    dom.askInput.value = '';
    setAsking(true);
    renderAsk();
    scrollThread();

    loadCuisines().then(function (cuisines) {
      var own = readWish(question, cuisines);
      var earlier = null;
      for (var i = state.asks.length - 1; i >= 0 && !earlier; i--) earlier = state.asks[i].wish;
      var wish = window.TTBAsk.carry(earlier || null, own);
      turn.wish = wish;

      return whereabouts(own).then(function (here) {
        return fetch(ASK_URL, {
          method: 'POST',
          headers: { 'content-type': 'application/json', accept: 'application/json' },
          body: JSON.stringify({
            q: question, lang: state.lang, wish: wish, here: here, history: history
          })
        });
      })
        .then(function (res) { return res.ok ? res.json() : null; })
        .catch(function () { return null; })
        .then(function (out) { arrive(turn, wish, out); });
    })
      .catch(function () { arrive(turn, null, null); });
  }

  function arrive(turn, wish, out) {
    var open = (out && out.open) || {};
    var city = ((out && out.venues) || []).filter(function (row) {
      return typeof row.lat === 'number' && typeof row.lng === 'number';
    }).map(cityStandIn);
    var model = out && out.source === 'ai' ? out : null;

    if (out && out.source === 'resting') {
      turn.say = t('askResting');
      turn.picks = [];
      turn.city = [];
      turn.open = open;
      turn.source = 'resting';
      turn.pending = false;
      settle(turn);
      TTBTrack.event('ask_resting', { search_term: turn.q.toLowerCase() });
      return;
    }

    var said = model && ((model.picks && model.picks.length) || model.say)
      ? { say: model.say || '', picks: model.picks || [], source: 'ai' }
      : { say: '', picks: [], source: 'none' };

    var at = '';
    if (out && out.at && (said.picks.length || (wish && wish.nearby))) {
      if (out.at.here) at = t('askFromHere');
      else if (typeof out.at.label === 'string') {
        at = t('askFrom', { name: [out.at.label, out.at.where].filter(Boolean).join(', ') });
      }
    }

    var named = {};
    said.picks.forEach(function (pick) { named[pick.id] = true; });
    var fromCity = city.filter(function (row) { return named[row.id]; });

    turn.say = said.say;
    turn.picks = said.picks;
    turn.city = fromCity;
    turn.open = open;
    turn.at = at;
    turn.source = said.source;
    turn.pending = false;
    settle(turn);

    TTBTrack.event(said.picks.length ? 'ask_answer' : 'ask_none', {
      search_term: turn.q.toLowerCase(),
      source: said.source,
      places_shown: said.picks.length,
      from_google: fromCity.length
    });
  }

  function settle(turn) {
    var newest = state.asks[state.asks.length - 1] === turn;
    if (!state.asks.some(function (t2) { return t2.pending; })) setAsking(false);
    if (newest && turn.picks.length && state.view !== 'detail') showAnswer(turn);
    else if (state.view === 'ask') { renderAsk(); if (newest) scrollThread(); }
  }

  function cityStandIn(row) {
    return {
      id: row.id,
      name: row.name,
      address: row.address || '',
      lat: row.lat,
      lng: row.lng,
      types: row.types || [],
      kitchens: row.kitchens || [],
      price: typeof row.price === 'number' ? row.price : null,
      rating: typeof row.rating === 'number' ? row.rating : null,
      reviews: typeof row.reviews === 'number' ? row.reviews : null,
      google: true,
      phone: row.phone || '',
      website: row.website || '',
      hours: row.hours || [],
      mapsUrl: row.mapsUrl || '',
      standIn: true
    };
  }

  function showAnswer(turn) {
    if (state.results) {
      forgetResults({ redraw: false });
      state.find = '';
      dom.findInput.value = '';
      dom.findClear.hidden = true;
    }
    forgetList();
    state.active = [];
    setQuery('');

    dropPins(state.askPlaces);
    state.answer = { picks: turn.picks, open: turn.open };
    state.askPlaces = turn.city;
    addPins(turn.city);
    state.selected = null;
    state.view = 'ask';

    if (state.marked && !answerWhy(state.marked)) state.marked = null;

    renderFilters();
    renderPanel();
    openPanel();
    openSheetAt(true);
    paintMarkers();
    fitToPins({ animate: true });
    scrollThread();
  }

  function forgetAnswer(opts) {
    if (!state.answer) return;
    state.answer = null;

    var standing = {};
    state.askPlaces.forEach(function (p) { standing[p.id] = true; });
    if (state.selected && standing[state.selected]) state.selected = null;
    if (state.marked && standing[state.marked]) state.marked = null;
    dropPins(state.askPlaces);
    state.askPlaces = [];
    if (state.view === 'ask' || !state.selected) state.view = 'list';
    if (opts && opts.redraw === false) return;
    renderPanel();
    paintMarkers();
  }

  function scrollThread() {
    dom.panelScroll.scrollTop = dom.panelScroll.scrollHeight;
  }

  function renderAsk() {
    while (dom.askThread.children.length > 1) dom.askThread.removeChild(dom.askThread.lastChild);

    state.asks.forEach(function (turn, i) {
      var newest = i === state.asks.length - 1;

      var say = turn.say ||
        (turn.pending ? t('askThinking') : turn.picks.length ? t('askHere') : t('askNothing'));

      var rows = el('ul', { className: 'place-list is-answer' });
      turn.picks.forEach(function (pick) {
        var place = byId(pick.id);
        if (!place) {
          for (var j = 0; j < turn.city.length; j++) {
            if (turn.city[j].id === pick.id) place = turn.city[j];
          }
        }
        if (!place) return;
        var far = farWords(pick.far);
        rows.appendChild(place.standIn ? listOnlyRow(place, pick.why || '', far) : listRow(place, pick.why || '', far));
      });

      dom.askThread.appendChild(el('article', {
        className: 'ask-turn' + (turn.pending ? ' is-pending' : ''),
        'aria-live': newest ? 'polite' : null
      }, [
        el('p', { className: 'ask-you', textContent: turn.q }),
        el('p', { className: 'ask-say', textContent: say }),
        turn.at ? el('p', { className: 'ask-from', textContent: turn.at }) : null,
        turn.picks.length ? rows : null
      ]));
    });
  }

  function openAsk(opts) {
    if (!state.lastFocus) state.lastFocus = document.activeElement;
    state.selected = null;
    state.view = 'ask';
    renderPanel();
    openPanel();

    openSheetAt(true);
    paintMarkers();
    scrollThread();

    if (opts && opts.keyboard === false) {
      var heading = dom.panel.querySelector('#panel-ask-title');
      if (heading) heading.focus();
      return;
    }

    try {
      dom.askInput.focus({ preventScroll: true });
    } catch (e) {
      dom.askInput.focus();
    }
  }

  var SHEET_HEADROOM = 158;
  var SHEET_PULL = 90;
  var SHEET_DISMISS = 60;

  var PEEK_AIR = 10;

  function safeInset(name) {
    var raw = getComputedStyle(document.documentElement).getPropertyValue(name);
    var n = parseFloat(raw);
    return isFinite(n) ? n : 0;
  }

  function peekStop() {
    return bandIsUp()
      ? dom.panelBand.offsetHeight + PEEK_AIR + safeInset('--safe-b')
      : 0;
  }

  function measureBand() {
    var h = peekStop();
    if (h) document.body.style.setProperty('--peek-h', h + 'px');
  }

  function sheetStops() {
    var h = window.innerHeight;
    var cap = Math.max(h - SHEET_HEADROOM - safeInset('--safe-t'), 160);
    var detail = document.body.classList.contains('panel-detail');
    return {
      peek: peekStop(),
      low: Math.min(h * .50, 470, cap),
      high: detail ? Math.min(h * .88, 780, cap) : Math.min(h * .82, 720, cap)
    };
  }

  function sheetHeightAt(px, stops) {
    if (px >= stops.low) return Math.min(px, stops.high);
    if (stops.peek) return Math.max(px, stops.peek);
    return stops.low - Math.min((stops.low - px) / 3, SHEET_PULL);
  }

  function sheetClosing(height, stops) {
    return !stops.peek && height < stops.low - SHEET_DISMISS;
  }

  function settleSheet(height, stops) {
    if (sheetClosing(height, stops)) { closePanel(); return; }
    if (stops.peek && height < (stops.peek + stops.low) / 2) { sheetPeek(); return; }
    sheetSnap(height > (stops.low + stops.high) / 2);
  }

  function sheetSnap(full) {
    document.body.classList.remove('sheet-peek');
    document.body.classList.toggle('sheet-full', !!full);
    if (dom.sheetGrip) dom.sheetGrip.setAttribute('aria-expanded', String(!!full));
    if (state.selected && state.view === 'detail') {
      var place = byId(state.selected);
      if (place) refocus(place, false);
    }
  }

  function sheetPeek() {
    document.body.classList.remove('sheet-full');
    document.body.classList.add('sheet-peek');
    if (dom.sheetGrip) dom.sheetGrip.setAttribute('aria-expanded', 'false');
  }

  function setSheetHeight(px) {
    document.body.style.setProperty('--sheet-h', Math.round(px) + 'px');
  }

  function releaseSheetHeight() {
    document.body.style.removeProperty('--sheet-h');
  }

  function openSheetAt(full) {
    full = !!full && isNarrow();
    document.body.classList.remove('sheet-peek');
    document.body.classList.toggle('sheet-full', full);
    if (dom.sheetGrip) dom.sheetGrip.setAttribute('aria-expanded', String(full));
    releaseSheetHeight();
  }

  function wireSheet() {
    if (!dom.sheetGrip) return;
    var dragging = false;
    var startY = 0;
    var startH = 0;
    var height = 0;
    var moved = false;
    var stops = null;

    function begin(ev) {
      if (!isNarrow() || !dom.panel.classList.contains('is-open')) return;
      dragging = true;
      moved = false;
      startY = ev.clientY;
      startH = dom.panel.offsetHeight;
      height = startH;
      stops = sheetStops();
      dom.panel.classList.add('is-dragging');
      if (dom.sheetGrip.setPointerCapture) dom.sheetGrip.setPointerCapture(ev.pointerId);
    }

    function move(ev) {
      if (!dragging) return;
      var delta = startY - ev.clientY;
      if (Math.abs(delta) > 4) moved = true;
      height = sheetHeightAt(startH + delta, stops);
      setSheetHeight(height);
      ev.preventDefault();
    }

    function end() {
      if (!dragging) return;
      dragging = false;
      dom.panel.classList.remove('is-dragging');
      releaseSheetHeight();

      if (!moved) { toggle(); return; }
      settleSheet(height, stops);
    }

    function toggle() {
      if (document.body.classList.contains('sheet-peek')) { sheetSnap(true); return; }
      sheetSnap(!document.body.classList.contains('sheet-full'));
    }

    dom.sheetGrip.addEventListener('pointerdown', begin);
    dom.sheetGrip.addEventListener('pointermove', move);
    dom.sheetGrip.addEventListener('pointerup', end);
    dom.sheetGrip.addEventListener('pointercancel', end);
    dom.sheetGrip.addEventListener('keydown', function (ev) {
      if (ev.key === 'Enter' || ev.key === ' ' || ev.key === 'Spacebar') {
        ev.preventDefault();
        toggle();
      }
    });

    dom.panel.addEventListener('focusin', function (ev) {
      if (!isNarrow() || document.body.classList.contains('sheet-full')) return;
      if (!ev.target.closest || !ev.target.closest('input, textarea')) return;
      sheetSnap(true);
    });

    wireSheetSwipe();
    wireResultSwipe();
  }

  function wireSheetSwipe() {
    var scroll = dom.panelScroll;
    if (!scroll) return;
    var armed = false;
    var active = false;
    var startX = 0;
    var startY = 0;
    var startH = 0;
    var height = 0;
    var stops = null;

    function ignore(node) {
      if (!node || !node.closest) return false;
      if (node.closest('iframe')) return true;
      var field = node.closest('input, textarea');
      return !!field && field === document.activeElement;
    }

    scroll.addEventListener('touchstart', function (ev) {
      armed = false;
      if (!isNarrow() || !dom.panel.classList.contains('is-open')) return;
      if (ev.touches.length !== 1 || ignore(ev.target)) return;
      armed = scroll.scrollTop <= 0;
      active = false;
      startX = ev.touches[0].clientX;
      startY = ev.touches[0].clientY;
      startH = dom.panel.offsetHeight;
      height = startH;
      stops = sheetStops();
    }, { passive: true });

    scroll.addEventListener('touchmove', function (ev) {
      if (!armed || ev.touches.length !== 1) return;
      var dy = ev.touches[0].clientY - startY;
      if (!active) {
        var dx = ev.touches[0].clientX - startX;
        if (Math.abs(dx) > 9 && Math.abs(dx) > Math.abs(dy)) { armed = false; return; }
        if (dy < 9) {
          if (dy < -3) armed = false;   /* they are scrolling, not dismissing */
          return;
        }
        active = true;
        dom.panel.classList.add('is-dragging');
      }
      height = sheetHeightAt(startH - dy, stops);
      setSheetHeight(height);
      if (ev.cancelable) ev.preventDefault();
    }, { passive: false });

    function release() {
      if (!armed) return;
      armed = false;
      if (!active) return;
      active = false;
      dom.panel.classList.remove('is-dragging');
      releaseSheetHeight();
      settleSheet(height, stops);
    }

    scroll.addEventListener('touchend', release);
    scroll.addEventListener('touchcancel', release);
  }

  function wireTopGuard() {
    var held = false;

    function above(y) {
      if (!dom.filterBar || !map || !map.dragging) return false;
      return y <= dom.filterBar.getBoundingClientRect().bottom;
    }

    function hold(ev) {
      if (held) return;
      var y = ev.touches && ev.touches.length ? ev.touches[0].clientY : ev.clientY;
      if (typeof y !== 'number' || !above(y)) return;
      held = true;
      map.dragging.disable();
    }

    function release() {
      if (!held) return;
      held = false;
      if (map && map.dragging) map.dragging.enable();
    }

    ['pointerdown', 'touchstart', 'mousedown'].forEach(function (type) {
      document.addEventListener(type, hold, true);
    });
    ['pointerup', 'pointercancel', 'touchend', 'touchcancel', 'mouseup'].forEach(function (type) {
      document.addEventListener(type, release, true);
    });
  }

  var BROWSER_BAR_MAX = 90;

  function viewportCovered() {
    var vv = window.visualViewport;
    if (!vv) return 0;
    if (vv.scale && Math.abs(vv.scale - 1) > .01) return 0;
    var covered = window.innerHeight - vv.height - vv.offsetTop;
    return covered > 0 ? Math.round(covered) : 0;
  }

  function syncViewportHeight() {
    var css = document.documentElement.style;
    var covered = viewportCovered();
    css.setProperty('--vph', window.innerHeight + 'px');
    css.setProperty('--browser-b', (covered > BROWSER_BAR_MAX ? 0 : covered) + 'px');
    return covered;
  }

  function wireKeyboard() {
    syncViewportHeight();
    window.addEventListener('resize', syncViewportHeight);
    window.addEventListener('orientationchange', syncViewportHeight);

    var vv = window.visualViewport;
    if (!vv) return;

    function sync() {
      var covered = syncViewportHeight();
      var kbd = covered > BROWSER_BAR_MAX ? covered : 0;
      document.documentElement.style.setProperty('--kbd', kbd + 'px');
      if (kbd && window.pageYOffset) window.scrollTo(0, 0);
    }

    vv.addEventListener('resize', sync);
    vv.addEventListener('scroll', sync);
    sync();
  }

  function openPanel() {
    dom.panel.classList.add('is-open');
    dom.panel.removeAttribute('inert');
    document.body.classList.add('panel-open');
    dom.btnList.setAttribute('aria-expanded', 'true');
    dismissWelcome(false);
    closeHints();
  }

  function restOnBand() {
    var was = state.selected;
    if (state.view === 'ask') state.asks = [];
    if (was) state.marked = was;
    showList(false);
    sheetPeek();
    if (was) {
      var seen = byId(was);
      if (seen) focusOn(seen, true);
    }
  }

  function restOnList() {
    var was = state.selected;
    if (state.view === 'ask') state.asks = [];
    if (was) state.marked = was;
    showList(false, { keepList: true });
  }

  function closePanel(opts) {
    if (!dom.panel.classList.contains('is-open')) return;
    var row = state.fromRow;
    if (row && state.list && state.view === 'detail' && state.selected === row &&
        (!opts || opts.band !== false)) {
      state.fromRow = null;
      state.selected = null;
      lastReelKey = null;
      standOn(byId(row));
      return;
    }
    if (state.list && isNarrow() && (!opts || opts.band !== false)) { restOnBand(); return; }
    if (listIsFixed() && (!opts || opts.band !== false)) { restOnList(); return; }
    if (state.view === 'detail' && state.answer && (!opts || opts.band !== false)) {
      lastReelKey = null;
      openAsk({ keyboard: false });
      if (!opts || opts.history !== false) syncUrl();
      TTBTrack.seen();
      return;
    }
    var was = state.selected;
    if (state.view === 'ask') {
      state.asks = [];
      forgetAnswer({ redraw: false });
    }
    dom.panel.classList.remove('is-open');
    dom.panel.setAttribute('inert', '');
    document.body.classList.remove('panel-open', 'sheet-full', 'sheet-peek');
    if (dom.sheetGrip) dom.sheetGrip.setAttribute('aria-expanded', 'false');
    releaseSheetHeight();
    lastSheetKey = null;
    dom.btnList.setAttribute('aria-expanded', 'false');

    state.selected = null;
    if (was) state.marked = was;
    state.view = 'list';
    lastReelKey = null;
    renderPanel();          /* leave the crawlable list in the markup */
    paintMarkers();
    if (!opts || opts.history !== false) syncUrl();
    TTBTrack.seen();

    if (was) {
      var seen = byId(was);
      if (seen) focusOn(seen, true);
    }

    var back = state.lastFocus;
    state.lastFocus = null;
    if (back && document.contains(back) && typeof back.focus === 'function') back.focus();

    if (introPending) introduceRail();
  }

  function selectPlace(id, opts) {
    opts = opts || {};
    var place = byId(id);
    if (!place) return;
    if (!state.lastFocus) state.lastFocus = document.activeElement;

    var fresh = !state.selected;
    if (id !== state.fromRow) state.fromRow = null;
    state.selected = id;
    state.marked = id;
    state.view = 'detail';
    renderPanel({ keepList: true });
    openPanel();
    openSheetAt(false);
    if (opts.history !== false) syncUrl(fresh);

    paintMarkers();
    refocus(place, !!opts.fly, opts.withHere);

    dom.panelScroll.scrollTop = 0;
    dom.detail.scrollTop = 0;
    var heading = dom.detail.querySelector('.place-name');
    if (heading) heading.focus();

    TTBTrack.view(place.name);
    countPress('place', place.id);
    if (layoutFresh && !opts.arrived && !layoutOpened) {
      layoutOpened = true;
      postPress('layout', state.layout + '-opened');
    }
    if (isFound(id) || isSavedStandIn(id)) dressFound(place);
  }

  function showList(focus, opts) {
    if (!state.lastFocus) state.lastFocus = document.activeElement;
    forgetAnswer({ redraw: false });
    state.selected = null;
    state.view = 'list';
    renderPanel(opts);
    openPanel();
    openSheetAt(!state.list);
    paintMarkers();
    syncUrl();
    dom.panelScroll.scrollTop = 0;
    if (focus) {
      var heading = dom.panel.querySelector('#panel-list-title');
      if (heading) heading.focus();
    }
  }

  function openFromRow(place) {
    state.fromRow = place.id;
    selectPlace(place.id, { fly: true, arrived: true });
  }

  function standOn(place) {
    state.marked = place.id;
    showList(false);
    fitToPins({ clearPanel: true });
    focusOn(place, false);
    showRow(place.id);
  }

  var ROW_AIR = 12;

  function showRow(id) {
    var scroll = dom.panelScroll;
    var stuck = dom.list.querySelector('.search');
    var rows = dom.listBody.querySelectorAll('.list-row');
    for (var i = 0; i < rows.length; i++) {
      if (rows[i].getAttribute('data-id') !== id) continue;
      var top = rows[i].getBoundingClientRect().top -
                scroll.getBoundingClientRect().top + scroll.scrollTop;
      scroll.scrollTop = Math.max(top - (stuck ? stuck.offsetHeight : 0) - ROW_AIR, 0);
      return;
    }
  }

  function markOpenRow() {
    var rows = dom.listBody.querySelectorAll('.list-row');
    for (var i = 0; i < rows.length; i++) {
      rows[i].classList.toggle('is-open', rows[i].getAttribute('data-id') === state.selected);
    }
  }

  function bandIsUp() {
    return !!state.list && listOnScreen();
  }

  function renderBand() {
    var up = bandIsUp();
    clear(dom.panelBand);
    dom.panelBand.hidden = !up;
    if (!up) {
      document.body.style.setProperty('--band-h', '0px');
      document.body.classList.remove('sheet-peek');
      return;
    }
    dom.panelBand.appendChild(listBand());
    measureBand();
    document.body.style.setProperty('--band-h', dom.panelBand.offsetHeight + 'px');
  }

  var lastListUp = false;

  function listOnScreen() {
    var busy = (state.view === 'detail' && state.selected) || state.view === 'ask';
    return !busy || (pairFits() && !isNarrow());
  }

  function renderPanel(opts) {
    document.body.classList.toggle('panel-detail', state.view === 'detail' && !!state.selected);
    if (routeFor && (state.view !== 'detail' || state.selected !== routeFor)) clearRoute();
    paintSave();
    paintShare();
    paintDirections();
    renderBand();
    var detail = state.view === 'detail' && state.selected;
    var asking = state.view === 'ask';
    document.title = detail
      ? byId(state.selected).name + ' | Tallinn Tastebuds'
      : t('documentTitle');
    document.body.classList.toggle('panel-ask', asking);
    var listUp = listOnScreen();
    if (detail) renderDetail(byId(state.selected)); else clear(dom.detail);
    var steps = detail && resultStepper();
    if (steps) dom.detail.insertBefore(steps, dom.detail.firstChild);
    if (asking) renderAsk();
    var keep = opts && opts.keepList && lastListUp && dom.listBody.firstChild;
    if (listUp && !keep) renderList();
    if (listUp) markOpenRow();
    lastListUp = listUp;
    dom.detail.hidden = !detail;
    dom.ask.hidden = !asking;
    dom.list.hidden = !listUp;
    dom.panel.setAttribute('aria-labelledby',
      detail ? 'panel-title' : asking ? 'panel-ask-title' : 'panel-list-title');
  }

  function priceGauge(n) {
    var wrap = el('span', {
      className: 'price',
      role: 'img',
      'aria-label': t('priceOf', { n: formatDecimal(n) })
    });
    for (var i = 1; i <= 4; i++) {
      var fill = n - i + 1;
      if (fill >= 1) {
        wrap.appendChild(el('i', { className: 'on', textContent: '€' }));
      } else if (fill >= 0.5) {
        wrap.appendChild(el('i', { className: 'half', textContent: '€' }, [
          el('b', { 'aria-hidden': 'true', textContent: '€' })
        ]));
      } else {
        wrap.appendChild(el('i', { textContent: '€' }));
      }
    }
    return wrap;
  }

  function formatDecimal(n, digits) {
    if (typeof n !== 'number' || !isFinite(n)) return String(n);
    if (typeof digits !== 'number') digits = n % 1 === 0 ? 0 : 1;
    try {
      return n.toLocaleString(state.lang, {
        minimumFractionDigits: digits,
        maximumFractionDigits: digits
      });
    } catch (e) {
      return n.toFixed(digits);
    }
  }

  function directionsUrl(place, key) {
    var dest = place.address ? place.name + ', ' + place.address
      : key ? place.name
      : place.lat + ',' + place.lng;
    return 'https://www.google.com/maps/dir/?api=1&destination=' + encodeURIComponent(dest) +
      (key ? '&destination_place_id=' + encodeURIComponent(key) : '');
  }

  function directionsButton(place, key) {
    return TTBTrack.click(el('a', {
      className: 'link-btn is-primary',
      'data-directions': true,
      href: directionsUrl(place, key),
      target: '_blank',
      rel: 'noopener',
      textContent: t('directions')
    }), 'directions', { place: place.name });
  }

  function callButton(place) {
    var link = el('a', {
      className: 'link-btn call-btn',
      href: telHref(place.phone),
      'aria-label': t('call') + ' ' + place.name + ', ' + place.phone
    }, [
      el('span', {
        className: 'call-icon',
        html: '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M5.2 1.6c.4 0 .8.3.9.7l.8 2.4c.1.4 0 .8-.3 1l-1.1.9c.8 1.7 2.2 3.1 3.9 3.9l.9-1.1c.2-.3.6-.4 1-.3l2.4.8c.4.1.7.5.7.9v2.3c0 .6-.5 1.1-1.1 1C7.6 14.5 1.5 8.4 1.1 1.7c0-.6.4-1.1 1-1.1h3.1z"/></svg>'
      }),
      el('span', { textContent: t('call') })
    ]);
    link.addEventListener('click', function () {
      TTBTrack.event('call_place', { place: place.name });
    });
    return link;
  }

  function dealBlock(place, deal) {
    var offer = window.TTBPass.offerText(deal, state.lang);
    var rolled = !!window.TTBPass.rates(deal);
    var signIn = state.account.ready && !state.account.user;
    var passHref = 'deal.html?r=' + encodeURIComponent(place.id);
    var open;
    if (signIn) {
      open = el('button', {
        type: 'button',
        className: 'link-btn is-primary',
        textContent: t(rolled ? 'dealRollSignIn' : 'dealSignIn')
      });
      open.addEventListener('click', function () {
        TTBTrack.event('deal_signin', { place: place.name });
        accountThen = passHref;
        openAccount('in', '', 'deal');
      });
    } else {
      open = el('a', { className: 'link-btn is-primary', href: passHref, textContent: t('passGet') });
      open.addEventListener('click', function () {
        TTBTrack.event('deal_open', { place: place.name });
      });
    }

    var note = rolled ? (signIn ? 'dealRollMembers' : 'dealRollHint') : (signIn ? 'dealMembers' : '');

    return el('div', { className: 'deal-block' }, [
      offer ? el('p', { className: 'deal-offer', textContent: offer }) : null,
      note ? el('p', { className: 'muted-note', textContent: t(note) }) : null,
      open
    ]);
  }

  function dealMark(deal) {
    var offer = window.TTBPass.offerText(deal, state.lang);
    var found = /%\s*\d+(?:[.,]\d+)?(?:–\d+(?:[.,]\d+)?)?|\d+(?:[.,]\d+)?(?:–\d+(?:[.,]\d+)?)?\s*%/.exec(offer);
    return el('span', {
      className: 'deal-mark',
      textContent: found ? '−' + found[0].replace(/\s+/g, '') : t('filterDiscount')
    });
  }

  function section(labelKey, body) {
    return el('div', { className: 'section' }, [
      el('p', { className: 'eyebrow', textContent: t(labelKey) }),
      body
    ]);
  }

  function plainSection(kids) {
    return el('div', { className: 'section' }, kids);
  }

  function renderListOnly(place) {
    dom.detail.className = 'is-from-list';

    dom.detail.appendChild(el('div', { className: 'place-head' }, [
      el('h2', {
        className: 'place-name',
        id: 'panel-title',
        tabindex: '-1',
        textContent: place.name
      })
    ]));

    dom.detail.appendChild(el('p', { className: 'muted-note', textContent: standInNote(place) }));

    var said = listSay(place.id);
    if (said) {
      dom.detail.appendChild(el('p', { className: 'blurb', textContent: said }));
    }

    var source = sourceLine(place);
    if (source) dom.detail.appendChild(source);

    if (place.address || place.phone) {
      dom.detail.appendChild(el('dl', { className: 'facts' }, [
        place.address ? el('dt', { textContent: t('address') }) : null,
        place.address ? el('dd', { textContent: place.address }) : null,
        place.phone ? el('dt', { textContent: t('phone') }) : null,
        place.phone
          ? el('dd', {}, [
              TTBTrack.click(el('a', { href: telHref(place.phone), textContent: place.phone }), 'call_place', { place: place.name })
            ])
          : null
      ]));
    }

    var hours = hoursBlock(place);
    if (hours) dom.detail.appendChild(section('hours', hours));

    var ways = [];
    if (typeof place.lat === 'number' && typeof place.lng === 'number') {
      ways.push(directionsButton(place, place.google ? place.id : ''));
    }
    if (place.phone) ways.push(callButton(place));
    if (place.website) {
      ways.push(TTBTrack.click(el('a', {
        className: 'link-btn',
        href: place.website,
        target: '_blank',
        rel: 'noopener',
        textContent: t('website')
      }), 'website', { place: place.name }));
    }
    if (place.mapsUrl) {
      ways.push(TTBTrack.click(el('a', {
        className: 'link-btn',
        href: place.mapsUrl,
        target: '_blank',
        rel: 'noopener',
        textContent: t('googleSee')
      }), 'google_listing', { place: place.name }));
    }
    if (ways.length) dom.detail.appendChild(el('div', { className: 'link-row' }, ways));
  }

  function sourceLine(place) {
    if (!place.google) return null;
    var kinds = (place.types || []).map(typeLabel).filter(Boolean).join(' \u00b7 ');
    if (!kinds && !place.price && !place.rating) return null;
    return el('span', { className: 'place-source mono' }, [
      el('span', { textContent: t('googleSays') }),
      place.rating ? scoreMark(place) : null,
      place.price ? priceGauge(place.price) : null,
      kinds ? el('span', { textContent: kinds }) : null
    ]);
  }

  function googleMark(place) {
    return el('span', { className: 'depth-mark is-google' }, [
      el('span', { textContent: 'Google' }),
      place.rating ? el('span', { className: 'google-score', textContent: formatDecimal(place.rating, 1) }) : null
    ]);
  }

  function scoreMark(place) {
    var out = formatDecimal(place.rating, 1);
    if (place.reviews) {
      out += ' ' + t(place.reviews === 1 ? 'googleReviewsOne' : 'googleReviews', {
        n: formatDecimal(place.reviews, 0)
      });
    }
    return el('span', { className: 'score', textContent: out });
  }

  function hoursBlock(place) {
    var week = place.hours || [];
    if (week.length !== 7) return null;
    var names = (t('days') || '').split('|');
    if (names.length !== 7) return null;

    var today = tallinnWeekday();
    var dl = el('dl', { className: 'facts is-hours' });
    for (var i = 0; i < 7; i++) {
      var mark = i === today ? 'is-today' : null;
      dl.appendChild(el('dt', { className: mark, textContent: names[i] }));
      dl.appendChild(el('dd', {
        className: mark,
        textContent: week[i] ? week[i].split('-').join('\u2013') : t('closed')
      }));
    }
    return dl;
  }

  function tallinnWeekday() {
    var order = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    try {
      var name = new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Europe/Tallinn', weekday: 'short'
      }).format(new Date());
      var found = order.indexOf(name);
      if (found !== -1) return found;
    } catch (e) { /* no Intl, or no zone data: the reader's own day will do */ }
    return (new Date().getDay() + 6) % 7;
  }

  var googleFor = {};
  var ASKING = {};

  function googleBlock(place, holder) {
    var row = googleFor[place.id];
    if (row === ASKING || row === null) return;
    if (row) { fillGoogle(holder, place, row); return; }

    googleFor[place.id] = ASKING;
    getJSON('/api/venues?map=' + encodeURIComponent(place.id)).then(function (rows) {
      googleFor[place.id] = rows && rows[0] ? rows[0] : null;
    }, function () {
      googleFor[place.id] = null;
    }).then(function () {
      if (googleFor[place.id] && holder.parentNode && state.selected === place.id) {
        fillGoogle(holder, place, googleFor[place.id]);
      }
    });
  }

  function fillGoogle(holder, place, row) {
    var kids = [];

    var dir = dom.detail.querySelector('a[data-directions]');
    if (dir) dir.href = directionsUrl(place, row.id);
    paintDirections();

    if (typeof row.rating === 'number') {
      kids.push(el('p', { className: 'google-line' }, [scoreMark(row)]));
    }

    if (typeof row.rank === 'number' && typeof row.of === 'number') {
      kids.push(el('p', {
        className: 'google-line google-rank',
        textContent: t('venuesRankTitle', {
          n: formatDecimal(row.rank, 0),
          total: formatDecimal(row.of, 0)
        })
      }));
    }

    var now = row.closed ? { text: t('venuesShutFor'), open: false } : openingNow(row.hours);
    if (now) {
      kids.push(el('p', {
        className: 'google-line google-now' + (now.open ? ' is-open' : ''),
        textContent: now.text
      }));
    }

    var week = hoursBlock(row);
    if (week) kids.push(week);

    if (row.phone && !place.phone) {
      kids.push(el('dl', { className: 'facts' }, [
        el('dt', { textContent: t('phone') }),
        el('dd', {}, [
          TTBTrack.click(el('a', { href: telHref(row.phone), textContent: row.phone }), 'call_place', { place: place.name })
        ])
      ]));
    }

    kids.push(el('div', { className: 'link-row' }, [
      TTBTrack.click(el('a', {
        className: 'link-btn',
        href: 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(row.name) +
          '&query_place_id=' + encodeURIComponent(row.id),
        target: '_blank',
        rel: 'noopener',
        textContent: t('googleSee')
      }), 'google_listing', { place: place.name })
    ]));

    clear(holder);
    holder.appendChild(section('googleSays', el('div', { className: 'google-block' }, kids)));
  }

  function openingNow(week) {
    if (!week || week.length !== 7) return null;
    var now = Date.now();
    var wall = new Date(now + tallinnOffset(now));
    var day = (wall.getUTCDay() + 6) % 7;
    var minute = wall.getUTCHours() * 60 + wall.getUTCMinutes();

    var today = daySpans(week[day]);
    var i;
    for (i = 0; i < today.length; i++) {
      var from = today[i][0], to = today[i][1];
      if (to > from ? (minute >= from && minute < to) : (to < from && minute >= from)) {
        return { open: true, text: t('venuesOpenUntil', { time: clockAt(to) }) };
      }
    }
    var last = daySpans(week[(day + 6) % 7]);
    for (i = 0; i < last.length; i++) {
      if (last[i][1] < last[i][0] && minute < last[i][1]) {
        return { open: true, text: t('venuesOpenUntil', { time: clockAt(last[i][1]) }) };
      }
    }
    var next = null;
    for (i = 0; i < today.length; i++) {
      if (today[i][0] > minute && (next === null || today[i][0] < next)) next = today[i][0];
    }
    return next === null
      ? { open: false, text: t('venuesShutToday') }
      : { open: false, text: t('venuesOpensAt', { time: clockAt(next) }) };
  }

  function daySpans(day) {
    var out = [];
    var chunks = String(day || '').split(',');
    for (var i = 0; i < chunks.length; i++) {
      var at = /(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/.exec(chunks[i]);
      if (at) out.push([Number(at[1]) * 60 + Number(at[2]), Number(at[3]) * 60 + Number(at[4])]);
    }
    return out;
  }

  function clockAt(minutes) {
    var h = Math.floor(minutes / 60) % 24;
    var m = minutes % 60;
    return (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m;
  }

  function renderDetail(place) {
    clear(dom.detail);
    if (!place) return;
    if (place.standIn) return renderListOnly(place);

    dom.detail.className = place.closed ? 'is-closed' : '';

    var deal = liveDealFor(place);
    var watchUp = watchesOnInstagram(place);

    dom.detail.appendChild(el('div', { className: 'place-head' }, [
      place.closed
        ? el('div', { className: 'closed-flag' }, [
            el('span', { className: 'shut-glyph', 'aria-hidden': 'true', html: SHUT_GLYPH }),
            el('span', { textContent: isPaused(place) ? t('venuesShutFor') : t('closedFlag') })
          ])
        : null,
      el('h2', {
        className: 'place-name',
        id: 'panel-title',
        tabindex: '-1',
        textContent: place.name
      }),
      el('div', { className: 'head-meta' }, [
        priceGauge(place.price),
        deal ? dealMark(deal) : null,
        farBadge(place)
      ]),
      watchUp ? watchButton(place) : null
    ]));

    if (place.closed) {
      dom.detail.appendChild(el('p', {
        className: 'muted-note is-shut-note',
        textContent: t(closedNoteKey(place))
      }));
    }

    var blurb = blurbFor(place);
    if (blurb) {
      dom.detail.appendChild(el('p', {
        className: 'blurb' + (/^\s*TODO/i.test(blurb) ? ' is-todo' : ''),
        textContent: blurb
      }));
    }

    if (place.reel && !watchUp) {
      dom.detail.appendChild(section('video', reelBlock(place)));
    }

    if ((place.photos || []).length) {
      dom.detail.appendChild(section('photos', photoGrid(place)));
    }

    if (!place.reel && !(place.photos || []).length) {
      dom.detail.appendChild(section('markNone',
        el('p', { className: 'not-filmed', textContent: t('notFilmed') })
      ));
    }

    if ((place.types || []).length) {
      dom.detail.appendChild(section('types',
        el('div', { className: 'tag-row' }, place.types.map(function (id) {
          return el('span', { className: 'tag', textContent: typeLabel(id) });
        }))
      ));
    }

    if (deal) dom.detail.appendChild(section('passOffer', dealBlock(place, deal)));

    if ((place.mustOrder || []).length) {
      dom.detail.appendChild(section('mustOrder',
        el('ul', { className: 'dish-list' }, place.mustOrder.map(function (dish) {
          return el('li', { textContent: dish });
        }))
      ));
    }

    dom.detail.appendChild(plainSection([
      el('dl', { className: 'facts' }, [
        el('dt', { textContent: t('address') }),
        el('dd', { textContent: place.address }),
        place.phone ? el('dt', { textContent: t('phone') }) : null,
        place.phone
          ? el('dd', {}, [
              TTBTrack.click(el('a', { href: telHref(place.phone), textContent: place.phone }), 'call_place', { place: place.name })
            ])
          : null,
        place.visited ? el('dt', { textContent: t('visited') }) : null,
        place.visited ? el('dd', { textContent: formatMonth(place.visited) }) : null
      ]),
      el('div', { className: 'link-row' }, [
        directionsButton(place, googleFor[place.id] && googleFor[place.id] !== ASKING
          ? googleFor[place.id].id : ''),
        place.phone ? callButton(place) : null,
        place.website
          ? TTBTrack.click(el('a', {
              className: 'link-btn',
              href: place.website,
              target: '_blank',
              rel: 'noopener',
              textContent: t('website')
            }), 'website', { place: place.name })
          : null
      ])
    ]));

    var google = el('div', { className: 'google-holder' });
    dom.detail.appendChild(google);
    googleBlock(place, google);
  }

  function reelProvider(url) {
    if (/^https:\/\/www\.tiktok\.com\//.test(url || '')) return 'tiktok';
    if (/^https:\/\/www\.instagram\.com\//.test(url || '')) return 'instagram';
    return null;
  }

  function reelBlock(place) {
    countReel(place);
    return reelProvider(place.reel) === 'tiktok' ? embedTikTok(place) : embedInstagram(place);
  }

  function countReel(place) {
    if (lastReelKey === place.id) return;
    lastReelKey = place.id;
    TTBTrack.event('reel_load', { place: place.name, provider: reelProvider(place.reel) || 'unknown' });
  }

  function watchesOnInstagram(place) {
    return !!place.reel && reelProvider(place.reel) === 'instagram' && isNarrow();
  }

  function watchButton(place) {
    countReel(place);
    return el('div', { className: 'head-watch' }, [
      TTBTrack.click(
        el('a', { className: 'watch-btn', href: place.reel }, [
          el('span', { className: 'watch-icon', 'aria-hidden': 'true', html: PLAY_GLYPH }),
          el('span', { textContent: t('reelWatch') })
        ]),
        'reel_open', { place: place.name }
      )
    ]);
  }

  function embedTikTok(place) {
    var id = /\/video\/(\d{6,})/.exec(place.reel);
    var wrap = el('div', { className: 'reel-embed' });

    if (id) {
      wrap.appendChild(el('div', { className: 'reel-frame is-tiktok' }, [
        el('iframe', {
          src: 'https://www.tiktok.com/embed/v2/' + id[1],
          title: place.name + ' — ' + t('video'),
          allow: 'autoplay; encrypted-media; picture-in-picture; fullscreen',
          allowfullscreen: '',
          referrerpolicy: 'strict-origin-when-cross-origin',
          frameborder: '0',
          scrolling: 'no'
        })
      ]));
    }

    wrap.appendChild(reelFallback(place, 'videoFallback'));
    return wrap;
  }

  function embedInstagram(place) {
    var post = /\/(p|reels?|tv)\/([A-Za-z0-9_-]+)/.exec(place.reel);
    var kind = post && (post[1] === 'reels' ? 'reel' : post[1]);

    return el('div', { className: 'reel-embed' }, [
      post ? el('div', { className: 'reel-frame is-instagram' }, [
        el('iframe', {
          src: 'https://www.instagram.com/' + kind + '/' + post[2] + '/embed/',
          title: place.name + ' — ' + t('video'),
          allow: 'autoplay; clipboard-write; encrypted-media; picture-in-picture; fullscreen',
          allowfullscreen: '',
          referrerpolicy: 'strict-origin-when-cross-origin',
          frameborder: '0',
          scrolling: 'no'
        })
      ]) : null,
      reelFallback(place, 'reelFallback')
    ]);
  }

  function reelFallback(place, key) {
    return el('p', { className: 'reel-fallback' }, [
      TTBTrack.click(
        el('a', { href: place.reel, textContent: t(key) }),
        'reel_open', { place: place.name }
      )
    ]);
  }

  function wireReelMeasure() {
    window.addEventListener('message', function (ev) {
      if (!/^https:\/\/(www\.)?instagram\.com$/.test(ev.origin)) return;

      var frames = dom.detail.querySelectorAll('.reel-frame.is-instagram iframe');
      var frame = null;
      for (var i = 0; i < frames.length; i++) {
        if (frames[i].contentWindow === ev.source) { frame = frames[i]; break; }
      }
      if (!frame) return;

      var data = ev.data;
      if (typeof data === 'string') {
        try { data = JSON.parse(data); } catch (e) { return; }
      }

      var details = (data && data.details) || data;
      var height = Number(details && details.height);
      var width = frame.offsetWidth;
      if (!height || !width || height < 100) return;

      frame.parentNode.style.aspectRatio = width + ' / ' + height;
    });
  }

  function photoGrid(place) {
    var base = 'photos/' + place.id + '/';
    var grid = el('div', { className: 'photo-grid' });

    place.photos.forEach(function (file, i) {
      var button = el('button', {
        type: 'button',
        'aria-label': t('photoOf', { n: i + 1, total: place.photos.length })
      }, [
        el('img', {
          src: base + file,
          alt: place.name + ' — ' + t('photoOf', { n: i + 1, total: place.photos.length }),
          loading: 'lazy',
          decoding: 'async'
        })
      ]);
      button.addEventListener('click', function () {
        TTBTrack.event('photo_open', { place: place.name, photo_index: i + 1 });
        openLightbox(place, i, button);
      });
      grid.appendChild(button);
    });

    return grid;
  }

  function fold(value) {
    var out = String(value == null ? '' : value).toLowerCase();
    try { out = out.normalize('NFD').replace(/[\u0300-\u036f]/g, ''); } catch (e) { /* older engine */ }
    return out.replace(/[\u0131\u0130]/g, 'i').replace(/\u00f8/g, 'o').replace(/\u00df/g, 'ss');
  }

  var hayIndex = null;

  function labelWords(list, id) {
    for (var i = 0; i < list.length; i++) {
      if (list[i].id === id) {
        var entry = list[i];
        return Object.keys(entry).map(function (k) {
          return k === 'id' ? '' : entry[k];
        }).join(' ');
      }
    }
    return '';
  }

  function buildSearchIndex() {
    hayIndex = {};
    state.places.forEach(function (place) {
      hayIndex[place.id] = fold([
        place.name,
        place.address,
        (place.types || []).map(function (id) { return labelWords(state.types, id); }).join(' '),
        (place.mustOrder || []).join(' ')
      ].join(' '));
    });
  }

  function hasWords(hay, words) {
    var hit = 3;
    for (var i = 0; i < words.length; i++) {
      var word = words[i];
      if (hay.indexOf(word) !== -1) continue;
      if (word.length < 5) return 0;
      if (hay.indexOf(word.slice(0, Math.max(4, word.length - 2))) !== -1) {
        hit = Math.min(hit, 2);
        continue;
      }
      if (!hayWords(hay).some(function (w) { return oneSlip(word, w); })) return 0;
      hit = 1;
    }
    return hit;
  }

  var hayWordsCache = {};
  function hayWords(hay) {
    var got = hayWordsCache[hay];
    if (!got) {
      got = hay.split(/[\s\/,.;:()&'"\u2019+-]+/);
      hayWordsCache[hay] = got;
    }
    return got;
  }

  function oneSlip(a, b) {
    var la = a.length;
    var lb = b.length;
    if (a === b || Math.abs(la - lb) > 1 || lb < 4) return false;
    var i = 0;
    while (i < la && i < lb && a.charAt(i) === b.charAt(i)) i++;
    var ja = la - 1;
    var jb = lb - 1;
    while (ja >= i && jb >= i && a.charAt(ja) === b.charAt(jb)) { ja--; jb--; }
    if (la === lb) {
      if (ja === i) return true;
      return ja === i + 1 && a.charAt(i) === b.charAt(ja) && a.charAt(ja) === b.charAt(i);
    }
    return ja < i + 1 && jb < i + 1;
  }

  function bestOnly(rows, level) {
    var best = 0;
    for (var id in level) best = Math.max(best, level[id]);
    if (best < 3) return rows;
    return rows.filter(function (row) { return level[row.id] > 1; });
  }

  function matches(place, words, level) {
    var hit = hasWords((hayIndex && hayIndex[place.id]) || '', words);
    if (level) level[place.id] = hit;
    return hit > 0;
  }

  function searchWords() {
    var q = fold(state.q).replace(/\s+/g, ' ').replace(/^ | $/g, '');
    return q ? q.split(' ') : [];
  }

  var searchTimer = null;

  var searchHits = 0;

  function setQuery(value) {
    var next = String(value == null ? '' : value);
    if (dom.search.value !== next) dom.search.value = next;
    if (next === state.q) return;
    forgetAnswer({ redraw: false });
    state.q = next;
    dom.searchClear.hidden = !next;
    renderList();
    trackSearch(next);
  }

  function trackSearch(q) {
    if (searchTimer) clearTimeout(searchTimer);
    var term = q.trim();
    if (term.length < 2) return;
    searchTimer = setTimeout(function () {
      TTBTrack.event('search', { search_term: term.toLowerCase(), scope: 'map', results: searchHits });
    }, 900);
  }

  var FIND_MINE = 3;
  var FIND_CITY = 16;

  var findRoll = null;
  var findHay = null;
  var findKind = null;
  var findAsking = null;
  var findRows = [];
  var findTrackTimer = null;

  var findCuisines = [];
  var findLent = {};

  var findRated = {};

  var findLocating = null;
  var findNoFix = false;

  var findReturn = null;

  function findLoad() {
    if (findRoll) return Promise.resolve(findRoll);
    if (findAsking) return findAsking;
    findAsking = loadCuisines().then(function (cuisines) {
      findCuisines = cuisines;
      return getJSON('/api/places');
    }).then(function (answer) {
      var rows = [];
      var list = Array.isArray(answer) ? answer : (answer && answer.places) || [];
      findHay = {};
      findKind = {};
      findLent = {};
      findRated = {};
      for (var i = 0; i < list.length; i++) {
        var row = list[i];
        if (!row || !row.name) continue;
        if (byMapId(row.id) || (row.mapId && byMapId(row.mapId))) {
          if (row.kitchens && row.kitchens.length) {
            findLent[row.mapId || row.id] = fold(row.kitchens.map(kitchenWords).join(' '));
          }
          findRated[row.mapId || row.id] = {
            rating: row.rating,
            reviews: row.reviews,
            rank: row.rank,
            category: row.category || ''
          };
          continue;
        }
        if (typeof row.lat !== 'number' || typeof row.lng !== 'number') continue;
        findKind[row.id] = fold([
          row.category || '',
          (row.types || []).map(function (id) {
            return id === 'pub' ? '' : labelWords(state.types, id);
          }).join(' '),
          (row.kitchens || []).map(kitchenWords).join(' ')
        ].join(' '));
        findHay[row.id] = fold(row.name + ' ' + (row.address || '')) + ' ' + findKind[row.id];
        rows.push(row);
      }
      findRoll = rows;
      return findRoll;
    }).catch(function () {
      findRoll = [];
      findHay = {};
      findKind = {};
      findRated = {};
      return findRoll;
    });
    return findAsking;
  }

  function kitchenWords(id) {
    return labelWords(findCuisines, id) || labelWords(state.types, id);
  }

  function findPriced(place, wish) {
    if (!wish.cheap && !wish.fancy) return true;
    if (typeof place.price !== 'number') return false;
    return wish.cheap ? place.price <= 2 : place.price >= 3;
  }

  function findFrom(wish) {
    if (hereMarker) return measureList(state.places).here ? hereMarker.getLatLng() : null;
    if (wish.nearby && !wish.near && !findNoFix && !findLocating) {
      findLocating = locateOnce().then(function (point) {
        findLocating = null;
        if (!point) findNoFix = true;
        if (state.find) renderFound();
      });
    }
    return null;
  }

  function byMapId(id) {
    for (var i = 0; i < state.places.length; i++) {
      if (state.places[i].id === id) return state.places[i];
    }
    return null;
  }

  function findOrder(words, wish, away, level, tier, says, named) {
    var q = words.join(' ');
    return function (a, b) {
      if (level[a.id] !== level[b.id]) return level[b.id] - level[a.id];
      if (tier[a.id] !== tier[b.id]) return tier[b.id] - tier[a.id];
      if (says[a.id] !== says[b.id]) return says[b.id] - says[a.id];
      if (away && wish.nearby && away[a.id] !== away[b.id]) return away[a.id] - away[b.id];
      if (named) {
        var ah = fold(a.name).indexOf(q) === 0 ? 0 : 1;
        var bh = fold(b.name).indexOf(q) === 0 ? 0 : 1;
        if (ah !== bh) return ah - bh;
      }
      var ak = findRank(a);
      var bk = findRank(b);
      if (ak !== bk) return ak - bk;
      var as = findScore(findGoogle(a));
      var bs = findScore(findGoogle(b));
      if (as !== bs) return bs - as;
      return fold(a.name) < fold(b.name) ? -1 : 1;
    };
  }

  function findGoogle(row) {
    return byMapId(row.id) ? (findRated[row.id] || {}) : row;
  }

  function findRank(row) {
    var rank = findGoogle(row).rank;
    return typeof rank === 'number' ? rank : Infinity;
  }

  function findSays(row, words) {
    var name = fold(row.name);
    var category = fold(byMapId(row.id) ? (findRated[row.id] || {}).category || '' : row.category || '');
    for (var i = 0; i < words.length; i++) {
      if (wordAt(name, words[i]) < 2 && wordAt(category, words[i]) < 2) return 0;
    }
    return 1;
  }

  function findCity(words, wish, area, level, tier, says) {
    var hits = [];
    if (!findRoll) return hits;
    for (var i = 0; i < findRoll.length; i++) {
      var row = findRoll[i];
      if (area && !area.contains([row.lat, row.lng])) continue;
      var hit = hasWords(findHay[row.id] || '', words);
      if (hit && findPriced(row, wish)) {
        level[row.id] = hit;
        tier[row.id] = findTier(fold(row.name), findKind[row.id] || '', fold(row.address || ''), words);
        says[row.id] = findSays(row, words);
        hits.push(row);
      }
    }
    return hits;
  }

  var FIND_PRIOR = 50;
  var FIND_MEAN = 4.4;
  function findScore(row) {
    if (typeof row.rating !== 'number') return -1;
    var n = typeof row.reviews === 'number' ? row.reviews : 0;
    return (n * row.rating + FIND_PRIOR * FIND_MEAN) / (n + FIND_PRIOR);
  }

  function findMine(words, wish, away, area, level, tier, says) {
    var hits = [];
    var order = {};
    for (var i = 0; i < state.places.length; i++) {
      var place = state.places[i];
      if (place.closed) continue;
      if (area && !area.contains([place.lat, place.lng])) continue;
      var hay = ((hayIndex && hayIndex[place.id]) || '') + ' ' + (findLent[place.id] || '');
      var hit = hasWords(hay, words);
      if (hit && findPriced(place, wish)) {
        level[place.id] = hit;
        tier[place.id] = findTier(fold(place.name), fold([
          (place.types || []).map(function (id) { return labelWords(state.types, id); }).join(' '),
          (place.mustOrder || []).join(' ')
        ].join(' ')), fold(place.address || ''), words);
        says[place.id] = findSays(place, words);
        order[place.id] = i;
        hits.push(place);
      }
    }
    hits.sort(function (a, b) {
      if (level[a.id] !== level[b.id]) return level[b.id] - level[a.id];
      if (tier[a.id] !== tier[b.id]) return tier[b.id] - tier[a.id];
      if (says[a.id] !== says[b.id]) return says[b.id] - says[a.id];
      if (away && wish.nearby && away[a.id] !== away[b.id]) return away[a.id] - away[b.id];
      var as = findScore(findRated[a.id] || {});
      var bs = findScore(findRated[b.id] || {});
      if (as !== bs) return bs - as;
      return order[a.id] - order[b.id];
    });
    return hits;
  }

  function findTier(name, kind, where, words) {
    var low = 3;
    for (var i = 0; i < words.length && low > 0; i++) {
      var word = words[i];
      var n = wordAt(name, word);
      var k = wordAt(kind, word);
      var w = wordAt(where, word);
      if (!n && !k && !w && word.length >= 5) {
        word = word.slice(0, Math.max(4, word.length - 2));
        n = wordAt(name, word);
        k = wordAt(kind, word);
        w = wordAt(where, word);
      }
      var got;
      if (n >= 2 || k === 3) got = 3;
      else if (k === 2 && word.length >= 4) got = 2;
      else if (n === 1 || w >= 2) got = 1;
      else if (k || w) got = 0;
      else got = 1;
      low = Math.min(low, got);
    }
    return low;
  }

  var WORD_EDGE = /[\s\/,.;:()&'"’+-]/;
  function wordAt(hay, word) {
    var best = 0;
    var from = 0;
    var i;
    while (best < 3 && (i = hay.indexOf(word, from)) !== -1) {
      if (i === 0 || WORD_EDGE.test(hay.charAt(i - 1))) {
        var end = i + word.length;
        var j = end;
        while (j < hay.length && !WORD_EDGE.test(hay.charAt(j))) j++;
        best = Math.max(best, j - end <= (word.length < 3 ? 0 : 2) ? 3 : 2);
      } else {
        best = Math.max(best, 1);
      }
      from = i + 1;
    }
    return best;
  }

  function firmOnly(rows, tier, firm) {
    if (!firm) return rows;
    return rows.filter(function (row) { return tier[row.id] > 0; });
  }
  function anyFirm(rows, tier) {
    return rows.some(function (row) { return tier[row.id] > 0; });
  }

  function findArea(wish) {
    if (!map || wish.nearby || !state.places.length) return null;
    var view = findReturn || { bounds: map.getBounds(), zoom: map.getZoom() };
    var whole = map.getBoundsZoom(L.latLngBounds(state.places.map(function (p) {
      return [p.lat, p.lng];
    })));
    return view.zoom > whole + 0.5 ? view.bounds : null;
  }

  function findRow(place, mine, far) {
    var where = place.address || '';
    var line = far ? (where ? far + ' \u00b7 ' + where : far) : where;

    var pin = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    pin.setAttribute('class', 'find-pin');
    pin.setAttribute('viewBox', '0 0 24 24');
    pin.setAttribute('aria-hidden', 'true');
    pin.setAttribute('focusable', 'false');
    var path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('d', 'M12 21.2c4.3-4.2 6.4-7.5 6.4-10.2a6.4 6.4 0 1 0-12.8 0c0 2.7 2.1 6 6.4 10.2z');
    pin.appendChild(path);

    var row = el('button', {
      type: 'button',
      className: 'find-row' + (mine ? ' is-mine' : ''),
      'data-id': place.id,
      'aria-label': place.name + (where ? ', ' + where : '') + (far ? ', ' + far : '') +
        ', ' + (mine ? t('findOnMap') : t('findInCity'))
    }, [
      pin,
      el('span', { className: 'find-text' }, [
        el('span', { className: 'find-name', textContent: place.name }),
        el('span', { className: 'find-where', textContent: line })
      ])
    ]);
    row.addEventListener('click', function () { findPick(place.id, mine); });
    return row;
  }

  function findTyped() {
    return state.find.replace(/\s+/g, ' ').replace(/^ | $/g, '');
  }

  function findHits(typed, bounds) {
    var wish = readWish(typed, findCuisines);
    var words = wish.rest;
    if (!words.length && !wish.nearby && !wish.cheap && !wish.fancy) {
      words = fold(typed).split(' ');
    }

    var at = findFrom(wish);
    var away = at ? measureFrom(at, state.places.concat(findRoll || [])) : null;

    var area = bounds || findArea(wish);
    var outside = false;
    var level = {};
    var tier = {};
    var says = {};
    var mine = findMine(words, wish, away, area, level, tier, says);
    var city = findCity(words, wish, area, level, tier, says);
    if (!bounds && area && findRoll && !anyFirm(mine.concat(city), tier)) {
      area = null;
      outside = true;
      mine = findMine(words, wish, away, null, level, tier, says);
      city = findCity(words, wish, null, level, tier, says);
    }
    var firm = anyFirm(mine.concat(city), tier);
    mine = firmOnly(bestOnly(mine, level), tier, firm);
    city = firmOnly(bestOnly(city, level), tier, firm);
    var named = !city.some(function (row) { return hasWords(findKind[row.id] || '', words) === 3; });
    var rest = mine.slice(FIND_MINE).concat(city);
    rest.sort(findOrder(words, wish, away, level, tier, says, named));
    return {
      wish: wish,
      at: at,
      away: away,
      area: area,
      outside: outside,
      mine: mine.slice(0, FIND_MINE),
      city: rest
    };
  }

  function renderFound() {
    var typed = findTyped();

    findRows = [];
    clear(dom.findBody);

    if (!typed) {
      dom.findNote.textContent = '';
      dom.findOut.hidden = true;
      return;
    }

    var hits = findHits(typed);
    var wish = hits.wish;
    var away = hits.away;
    var area = hits.area;
    var outside = hits.outside;
    var far = function (place) { return away ? farWords(away[place.id] / 1000) : ''; };
    var mine = hits.mine;
    var city = hits.city;
    var shown = city.slice(0, FIND_CITY);

    if (mine.length) {
      dom.findBody.appendChild(el('p', { className: 'find-group', textContent: t('findOnMap') }));
      for (var m = 0; m < mine.length; m++) {
        var row = findRow(mine[m], true, far(mine[m]));
        findRows.push(row);
        dom.findBody.appendChild(row);
      }
    }

    if (shown.length) {
      dom.findBody.appendChild(el('p', {
        className: 'find-group',
        textContent: t(area ? 'findInArea' : 'findInCity')
      }));
      for (var c = 0; c < shown.length; c++) {
        var crow = findRow(shown[c], !!byMapId(shown[c].id), far(shown[c]));
        findRows.push(crow);
        dom.findBody.appendChild(crow);
      }
    }

    if (!findRoll) {
      dom.findNote.textContent = t('findLooking');
    } else if (!findRows.length) {
      dom.findNote.textContent = t('searchNone', { q: typed });
    } else if (wish.nearby && !wish.near && !away) {
      dom.findNote.textContent = t(findLocating ? 'findLocating' : hereMarker ? 'locateAway' : 'locateFail');
    } else if (outside) {
      dom.findNote.textContent = t('findNoneHere');
    } else if (area) {
      dom.findNote.textContent = t('findHere');
    } else if (city.length > shown.length) {
      dom.findNote.textContent = t('findMore', { n: city.length - shown.length });
    } else {
      dom.findNote.textContent = '';
    }

    dom.findOut.hidden = false;
  }

  function seatFound(row) {
    forgetFound({ redraw: false });
    var place = foundStandIn(row);
    state.foundPlaces = [place];
    addPins(state.foundPlaces);
    return place;
  }

  function foundStandIn(row) {
    return cityStandIn({
      id: row.id,
      name: row.name,
      address: row.address || '',
      lat: row.lat,
      lng: row.lng,
      types: row.types || [],
      price: typeof row.price === 'number' ? row.price : null,
      rating: typeof row.rating === 'number' ? row.rating : null,
      reviews: typeof row.reviews === 'number' ? row.reviews : null
    });
  }

  function dressFound(place) {
    if (place.dressed) return;
    place.dressed = true;
    getJSON('/api/venues?ids=' + encodeURIComponent(place.id)).then(function (rows) {
      if (!rows || !rows.length || !rows[0]) return;
      if (byId(place.id) !== place) return;
      var row = rows[0];
      place.phone = row.phone || '';
      place.website = row.website || '';
      place.hours = row.hours || [];
      if (state.selected === place.id) renderPanel({ keepList: true });
    }).catch(function () { /* the card stands without it */ });
  }

  function findPick(id, mine) {
    TTBTrack.event('find_pick', {
      search_term: state.find.trim().toLowerCase(),
      scope: mine ? 'map' : 'city'
    });
    dom.findOut.hidden = true;
    findRows = [];
    dom.findInput.blur();

    if (state.results) {
      if (state.results.ids.indexOf(id) !== -1) { selectPlace(id, { fly: true }); return; }
      forgetResults();
    }

    if (!findReturn) findReturn = { centre: map.getCenter(), zoom: map.getZoom(), bounds: map.getBounds() };

    if (mine) {
      forgetFound();
      selectPlace(id, { fly: true });
      return;
    }

    var row = null;
    for (var i = 0; findRoll && i < findRoll.length; i++) {
      if (findRoll[i].id === id) { row = findRoll[i]; break; }
    }
    if (!row) return;

    var place = seatFound(row);
    selectPlace(place.id, { fly: true });
  }

  function forgetFound(opts) {
    if (!state.foundPlaces.length) return;
    var standing = {};
    for (var i = 0; i < state.foundPlaces.length; i++) standing[state.foundPlaces[i].id] = true;
    if (state.selected && standing[state.selected]) {
      state.selected = null;
      state.view = 'list';
    }
    if (state.marked && standing[state.marked]) state.marked = null;
    dropPins(state.foundPlaces);
    state.foundPlaces = [];
    if (opts && opts.redraw === false) return;
    renderPanel();
    paintMarkers();
  }

  function setFind(next) {
    if (dom.findInput.value !== next) dom.findInput.value = next;
    if (next === state.find) return;
    state.find = next;
    dom.findClear.hidden = !next;

    if (!next) {
      if (state.results) {
        forgetResults();
        findReturn = null;
        renderFound();
        return;
      }
      forgetFound();
      if (findReturn) {
        cancelRefocus();
        travelTo(findReturn.centre, findReturn.zoom, true);
        findReturn = null;
      }
      renderFound();
      return;
    }

    renderFound();
    findLoad().then(function () {
      if (state.find === next) renderFound();
    });
    trackFind(next);
  }

  var FIND_RESULTS = 60;

  var findMoved = false;

  function resultPlaces() {
    var out = [];
    for (var i = 0; i < state.results.ids.length; i++) {
      var place = byId(state.results.ids[i]);
      if (place) out.push(place);
    }
    return out;
  }

  function submitFind(bounds) {
    var typed = findTyped();
    if (!typed) { dom.findInput.blur(); return; }
    findLoad().then(function () {
      if (findTyped() !== typed) return;
      var hits = findHits(typed, bounds);
      var found = hits.mine.concat(hits.city);
      if (!found.length) {
        if (bounds) {
          dom.findArea.hidden = true;
          toast(t('findNoneInArea', { q: typed }));
        } else {
          renderFound();
        }
        return;
      }
      showResults(typed, found, hits, bounds);
    });
  }

  function showResults(typed, found, hits, bounds) {
    var total = found.length;
    found = found.slice(0, FIND_RESULTS);

    forgetAnswer({ redraw: false });
    forgetList();
    forgetFound({ redraw: false });
    state.active = [];
    if (isNarrow() && filterMenuOpen()) closeFilterMenu();

    var city = [];
    var ids = [];
    for (var i = 0; i < found.length; i++) {
      var place = byMapId(found[i].id) ? found[i] : foundStandIn(found[i]);
      if (place !== found[i]) city.push(place);
      ids.push(place.id);
    }
    state.foundPlaces = city;
    addPins(city);
    state.results = { q: typed, ids: ids };
    findReturn = null;
    findMoved = false;
    document.body.classList.add('is-results');

    dom.findOut.hidden = true;
    findRows = [];
    dom.findInput.blur();
    dom.findArea.hidden = true;
    renderFilters();
    renderList();

    TTBTrack.event(bounds ? 'find_area' : 'find_submit', {
      search_term: typed.toLowerCase(),
      results: total
    });

    selectPlace(ids[0], { fly: false });
    if (!bounds) {
      cancelRefocus();
      window.setTimeout(function () {
        if (state.results && state.results.q === typed) fitToPins({ animate: true, clearPanel: true });
      }, isNarrow() && !reduceMotion() ? 320 : 0);
    }
    if (total > found.length) toast(t('findCapped', { n: found.length, total: total }));
  }

  function forgetResults(opts) {
    if (!state.results) return;
    state.results = null;
    findMoved = false;
    document.body.classList.remove('is-results');
    dom.findArea.hidden = true;
    forgetFound({ redraw: false });
    if (opts && opts.redraw === false) return;
    state.selected = null;
    state.view = 'list';
    renderFilters();
    renderPanel();
    if (isNarrow()) closePanel({ history: false });
    paintMarkers();
    cancelRefocus();
    fitToPins({ animate: true });
    syncUrl();
  }

  function stepResult(delta, how) {
    if (!state.results || !state.selected) return;
    var ids = state.results.ids;
    var at = ids.indexOf(state.selected);
    if (at === -1) return;
    var next = ids[(at + delta + ids.length) % ids.length];
    TTBTrack.event('find_step', { direction: delta > 0 ? 'next' : 'prev', by: how || 'arrow' });
    selectPlace(next, { fly: false });
  }

  function resultStepper() {
    if (!state.results || !state.selected) return null;
    var ids = state.results.ids;
    var at = ids.indexOf(state.selected);
    if (at === -1 || ids.length < 2) return null;
    var arrow = function (delta, key, d) {
      var btn = el('button', {
        type: 'button',
        className: 'result-step',
        'aria-label': t(key),
        title: t(key),
        html: '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="' + d + '"/></svg>'
      });
      btn.addEventListener('click', function () { stepResult(delta); });
      return btn;
    };
    return el('div', { className: 'result-steps' }, [
      arrow(-1, 'findPrev', 'M14.5 6l-6 6 6 6'),
      el('span', {
        className: 'result-count',
        textContent: t('findStep', { i: at + 1, n: ids.length })
      }),
      arrow(1, 'findNext', 'M9.5 6l6 6-6 6')
    ]);
  }

  var SWIPE_STEP = 60;

  function wireResultSwipe() {
    var card = dom.detail;
    var on = false;
    var startX = 0;
    var startY = 0;
    var dx = 0;
    var sideways = false;

    function scrollsSideways(node) {
      for (; node && node !== card; node = node.parentNode) {
        if (node.nodeType !== 1) continue;
        if (node.tagName === 'IFRAME' || node.tagName === 'VIDEO') return true;
        if (node.scrollWidth > node.clientWidth + 1) {
          var o = getComputedStyle(node).overflowX;
          if (o === 'auto' || o === 'scroll') return true;
        }
      }
      return false;
    }

    function pull(x) {
      if (reduceMotion()) return;
      card.style.transform = x ? 'translateX(' + Math.round(x / 3) + 'px)' : '';
    }

    card.addEventListener('touchstart', function (ev) {
      on = false;
      if (!state.results || !state.selected || state.view !== 'detail') return;
      if (state.results.ids.length < 2 || state.results.ids.indexOf(state.selected) === -1) return;
      if (ev.touches.length !== 1 || scrollsSideways(ev.target)) return;
      on = true;
      sideways = false;
      dx = 0;
      startX = ev.touches[0].clientX;
      startY = ev.touches[0].clientY;
    }, { passive: true });

    card.addEventListener('touchmove', function (ev) {
      if (!on || ev.touches.length !== 1) return;
      dx = ev.touches[0].clientX - startX;
      var dy = ev.touches[0].clientY - startY;
      if (!sideways) {
        if (Math.abs(dy) > 10 && Math.abs(dy) >= Math.abs(dx)) { on = false; return; }
        if (Math.abs(dx) < 10) return;
        sideways = true;
        card.classList.add('is-swiping');
      }
      pull(dx);
      if (ev.cancelable) ev.preventDefault();
    }, { passive: false });

    function release() {
      if (!on) return;
      on = false;
      card.classList.remove('is-swiping');
      pull(0);
      if (sideways && Math.abs(dx) >= SWIPE_STEP) stepResult(dx < 0 ? 1 : -1, 'swipe');
    }

    card.addEventListener('touchend', release);
    card.addEventListener('touchcancel', release);
  }

  function wireFindMoved() {
    var box = map.getContainer();
    var touched = function () { if (state.results) findMoved = true; };
    map.on('dragstart', touched);
    box.addEventListener('wheel', touched, { passive: true });
    box.addEventListener('dblclick', touched);
    box.addEventListener('touchstart', function (ev) {
      if (ev.touches && ev.touches.length > 1) touched();
    }, { passive: true });
    map.on('moveend', function () {
      if (!state.results || !findMoved) return;
      if (dom.findOut.hidden) dom.findArea.hidden = false;
    });
    dom.findArea.addEventListener('click', function () {
      dom.findArea.hidden = true;
      submitFind(map.getBounds());
    });
  }

  function trackFind(q) {
    if (findTrackTimer) clearTimeout(findTrackTimer);
    var term = q.trim();
    if (term.length < 2) return;
    findTrackTimer = setTimeout(function () {
      TTBTrack.event('search', { search_term: term.toLowerCase(), scope: 'find' });
    }, 900);
  }

  function findKey(ev) {
    if (ev.key !== 'ArrowDown' && ev.key !== 'ArrowUp') return;
    if (!findRows.length) return;
    ev.preventDefault();

    var at = findRows.indexOf(document.activeElement);
    if (ev.key === 'ArrowDown') {
      if (at === -1) { findRows[0].focus(); return; }
      if (at + 1 < findRows.length) findRows[at + 1].focus();
      return;
    }
    if (at <= 0) { dom.findInput.focus(); return; }
    findRows[at - 1].focus();
  }

  function farWords(km) {
    if (typeof km !== 'number' || !isFinite(km)) return '';
    return km < 1
      ? t('askMetres', { n: Math.max(50, Math.round(km * 20) * 50) })
      : t('askKm', { n: formatDecimal(km, 1) });
  }

