  function measureFrom(at, places) {
    var away = {};
    places.forEach(function (p) {
      away[p.id] = at.distanceTo(L.latLng(p.lat, p.lng));
    });
    return away;
  }

  function measureList(places) {
    var square = L.latLng(OLD_TOWN[0], OLD_TOWN[1]);
    if (!hereMarker) return { here: false, away: measureFrom(square, places) };

    var away = measureFrom(hereMarker.getLatLng(), places);
    var best = Infinity;
    places.forEach(function (p) { if (away[p.id] < best) best = away[p.id]; });
    if (best > HERE_MAX_M) return { here: false, away: measureFrom(square, places) };
    return { here: true, away: away };
  }

  function renderList() {
    cancelPeek();
    clear(dom.listBody);

    var words = searchWords();
    var places = visiblePlaces();
    if (words.length) {
      var level = {};
      places = bestOnly(places.filter(function (p) { return matches(p, words, level); }), level);
    }
    searchHits = places.length;

    var mine = !words.length && state.active.length === 1 &&
               state.active[0] === SAVED_FILTER;

    var reading = !words.length && !state.active.length && !!state.list;

    var from = null;

    if (state.results) {
      var step = {};
      state.results.ids.forEach(function (id, i) { step[id] = i; });
      places.sort(function (a, b) { return step[a.id] - step[b.id]; });
    } else if (reading) {
      var pos = {};
      state.list.items.forEach(function (item, i) { pos[item.place] = i; });
      places.sort(function (a, b) { return pos[a.id] - pos[b.id]; });
    } else if (mine) {
      var rank = {};
      state.saved.forEach(function (id, i) { rank[id] = i; });
      places.sort(function (a, b) { return rank[a.id] - rank[b.id]; });
    } else {
      from = measureList(places);
      var collator;
      try { collator = new Intl.Collator(state.lang, { sensitivity: 'base' }); }
      catch (e) { collator = { compare: function (a, b) { return a < b ? -1 : a > b ? 1 : 0; } }; }
      places.sort(function (a, b) {
        if (from.away[a.id] !== from.away[b.id]) return from.away[a.id] - from.away[b.id];
        return collator.compare(a.name, b.name);
      });
    }

    var titled = bandIsUp();

    if (!places.length) {
      dom.listBody.appendChild(el('h2', {
        className: 'empty-note',
        id: titled ? null : 'panel-list-title',
        tabIndex: titled ? null : -1,
        textContent: words.length ? t('searchNone', { q: state.q.trim() }) : t('noResults')
      }));
      return;
    }

    function farOf(place) {
      if (!from || !from.here) return '';
      return farWords(from.away[place.id] / 1000);
    }

    if (reading) {
      dom.listBody.appendChild(listCredit(places.length));
      var ul = el('ul', { className: 'place-list is-list' });
      places.forEach(function (place) { ul.appendChild(listRow(place, listSay(place.id))); });
      dom.listBody.appendChild(ul);
      return;
    }

    var name = state.results ? state.results.q
      : t(mine ? 'listSaved' : from.here ? 'listNearYou' : 'listNearOldTown');
    var count = places.length === 1 ? t('listCountOne') : t('listCount', { n: places.length });

    dom.listBody.appendChild(el('h2', {
      className: 'list-label',
      'aria-label': name + ', ' + count,
      id: titled ? null : 'panel-list-title',
      tabIndex: titled ? null : -1
    }, [
      el('span', { className: 'list-group', textContent: name }),
      el('span', { className: 'list-label-n eyebrow', textContent: count })
    ]));

    var group = el('ul', { className: 'place-list' });
    places.forEach(function (place) { group.appendChild(listRow(place, '', farOf(place))); });
    dom.listBody.appendChild(group);
  }

